  { id=273, name="Drak'Tharon Keep", isRaid=false, minLevel=70,
    mapID=600, loreFDID=608240, bgFDID=608162, buttonFDID=608201,
    desc="Drak'Tharon Keep once served the Drakkari trolls as a formidable outpost at the edge of their kingdom, Zul'Drak, but a recent Scourge invasion has delivered the fortress into the Lich King's hands. The keep's fallen defenders are now the Lich King's undead minions, and they are advancing into the heart of Drakkari territory.",
    encounters = {
      { id=588, name="Trollgore", order=1,
        uiMapID=160, x=0.5656, y=0.1824, rootSection=6370,
        desc="The Drakkari were among the most vicious troll tribes and Trollgore was a paragon of the tribe's savagery. This hulking monstrosity discovered that his vaunted ferocity paled in comparison to the Lich King's and he now serves as a grisly warning to all that dare challenge Arthas' reign.",
        creatures = { {display=26352, file=607798, name="Trollgore"} },
        loot = { {id=37714,pct=22.0,q=3,diff=6,name="Batrider's Cord"}, {id=35620,pct=33.0,q=3,diff=6,name="Berserker's Horns"}, {id=37715,pct=21.0,q=3,diff=6,name="Cowl of the Dire Troll"}, {id=37712,pct=22.0,q=3,diff=6,name="Terrace Defence Boots"}, {id=35618,pct=30.0,q=3,diff=6,name="Troll Butcherer"}, {id=35619,pct=28.0,q=3,diff=6,name="Infection Resistant Legguards"}, {id=37717,pct=22.0,q=3,diff=6,name="Legs of Physical Regeneration"} },
        sections = {
          { id=6370, title="Crush", parent=0, child=0, sib=6371, order=1, spell=0, icon="Interface\\icons\\ability_smash", flags=0, cdisp=0,
            body="Trollgore crushes a player, inflicting Physical damage." },
          { id=6371, title="Infected Wound", parent=0, child=0, sib=6372, order=2, spell=0, icon="Interface\\icons\\spell_nature_nullifydisease", flags=0, cdisp=0,
            body="Trollgore infects a player, increasing their Physical damage taken by $49637s1% for $49637d." },
          { id=6372, title="Consume", parent=0, child=0, sib=6373, order=3, spell=0, icon="Interface\\icons\\spell_shadow_blackplague", flags=0, cdisp=0,
            body="Trollgore consumes all enemies within $49380A1 yards, inflicting Shadow damage. For every enemy damage in this way, Trollgore gains $49381s2% damage increase.$[!2\n\nIn Heroic Difficulty, Trollgore gains $59805s2% damage increase from each enemy consumed.$]" },
          { id=6373, title="Corpse Explode", parent=0, child=0, sib=6374, order=4, spell=0, icon="Interface\\icons\\spell_nature_abolishmagic", flags=0, cdisp=0,
            body="Trollgore infests a nearby Drakkari Invader corpse, causing it to explode after a few seconds inflicting Nature damage to all players within $49618a1 yards." },
          { id=6374, title="Drakkari Invader", parent=0, child=0, sib=0, order=5, spell=0, icon=0, flags=0, cdisp=27079,
            body="Drakkari Invaders fly in and attack Trollgore and players throughout the fight." },
        },
      },
      { id=589, name="Novos the Summoner", order=2,
        uiMapID=160, x=0.7022, y=0.4795, rootSection=6375,
