      { id=598, name="Volkhan", order=2,
        uiMapID=139, x=0.377, y=0.209, rootSection=7042,
        desc="Loken's powerful legions are a testament to the craftsmanship of his blacksmith, Volkhan. His work is never ending, ceaselessly creating soldiers to fight for the fallen keeper. Only when the blacksmith's creations stand atop the crumpled bodies of their enemies will his work be done.",
        creatures = { {display=27071, file=607809, name="Volkhan"} },
        loot = { {id=37842,pct=21.0,q=3,diff=6,name="Belt of Vivacity"}, {id=36983,pct=22.0,q=3,diff=6,name="Cape of Seething Steam"}, {id=36986,pct=22.0,q=3,diff=6,name="Kilt of Molten Golems"}, {id=37841,pct=21.0,q=3,diff=6,name="Slag Footguards"}, {id=37840,pct=21.0,q=3,diff=6,name="Shroud of Reverberation"}, {id=36985,pct=23.0,q=3,diff=6,name="Volkhan's Hood"}, {id=36984,pct=22.0,q=3,diff=6,name="Eternally Folded Blade"}, {id=37843,pct=21.0,q=3,diff=6,name="Giant-Hair Woven Gloves"} },
