      { id=599, name="Ionar", order=3,
        uiMapID=139, x=0.6148, y=0.7746, rootSection=7252,
        desc="Loken does not rely on his iron minions as his personal defenders. The fallen keeper relies upon lightning itself. Ionar and its cohorts were given sanctuary within the Halls of Lightning in exchange for their unquestioning loyalty and willingness to slaughter any who seek to confront their new master.",
        creatures = { {display=27484, file=607663, name="Ionar"} },
        loot = { {id=39534,pct=21.0,q=3,diff=6,name="Pauldrons of the Lightning Revenant"}, {id=37844,pct=21.0,q=3,diff=6,name="Winged Talisman"}, {id=39657,pct=21.0,q=3,diff=6,name="Tornado Cuffs"}, {id=39536,pct=22.0,q=3,diff=6,name="Thundercloud Grasps"}, {id=37846,pct=20.0,q=3,diff=6,name="Charged-Bolt Grips"}, {id=39535,pct=21.0,q=3,diff=6,name="Ionar's Girdle"}, {id=37845,pct=21.0,q=3,diff=6,name="Cord of Swirling Winds"} },
