  { id=276, name="Halls of Reflection", isRaid=false, minLevel=70,
    mapID=668, loreFDID=608244, bgFDID=608166, buttonFDID=608205,
    desc="For many years, champions among the races of Azeroth have stood against the Lich King only to be slaughtered mercilessly and forced to serve in his army of undead horrors. In his ongoing struggle to stop the Lich King, Tirion Fordring of the Argent Crusade has joined forces with Darion Mograine of the Knights of the Ebon Blade in order to assault Icecrown Citadel with a unified army called the Ashen Verdict.",
    encounters = {
      { id=601, name="Falric", order=1,
        uiMapID=185, x=0.3525, y=0.75, rootSection=7265,
        desc="This champion of the Scourge was among the first death knights created by Arthas after claiming Frostmourne. Falric loyally followed his prince on a doomed campaign to Northrend only to be rewarded with betrayal by the prince he served faithfully all his life.",
