  { id=277, name="Halls of Stone", isRaid=false, minLevel=70,
    mapID=599, loreFDID=608245, bgFDID=608167, buttonFDID=608206,
    desc="Upon departing Azeroth, the titans entrusted loyal protectors with safeguarding Ulduar, an enigmatic city nestled in the mountains of the Storm Peaks. Designated supreme among his brethren was the guardian known as Loken, but with the power of the titan complex in his hands, he turned to darkness and plunged the region into chaos.",
    encounters = {
      { id=604, name="Krystallus", order=1,
        uiMapID=140, x=0.4016, y=0.6045, rootSection=7285,
        desc="War isn't won by might alone; it is won by armies. This inherent truth inspired Loken to order the creation of loyal stone constructs to bolster his legions. Krystallus was chosen to oversee the operation and to crush any interloper that threatens its work.",
        creatures = { {display=20909, file=607679, name="Krystallus"} },
        loot = { {id=37652,pct=28.0,q=3,diff=6,name="Spaulders of Krystallus"}, {id=35673,pct=29.0,q=3,diff=6,name="Leggings of Burning Gleam"}, {id=37650,pct=27.0,q=3,diff=6,name="Shardling Legguards"}, {id=35672,pct=30.0,q=3,diff=6,name="Hollow Geode Helm"}, {id=37651,pct=27.0,q=3,diff=6,name="The Prospector's Prize"}, {id=35670,pct=26.0,q=3,diff=6,name="Brann's Lost Mining Helmet"} },
        sections = {
          { id=7285, title="Ground Slam", parent=0, child=0, sib=7286, order=1, spell=0, icon="Interface\\icons\\inv_stone_11", flags=0, cdisp=0,
            body="Krystallus stomps the ground, knocking all players back and reducing their movement speed by $50836s1% every second. After $50833d, players are turned to stone, stunning them until they are Shattered." },
          { id=7286, title="Shatter", parent=0, child=0, sib=7287, order=2, spell=0, icon="Interface\\icons\\ability_bullrush", flags=0, cdisp=0,
            body="Krystallus shatters all players turned to stone, inflicting Physical damage to their allies based on proximity." },
          { id=7287, title="Boulder Toss", parent=0, child=0, sib=7288, order=3, spell=0, icon="Interface\\icons\\inv_datacrystal06", flags=0, cdisp=0,
            body="Krystallus hurls a boulder at a player, inflicting Physical damage." },
