      { id=605, name="Maiden of Grief", order=2,
        uiMapID=140, x=0.5027, y=0.8627, rootSection=7290,
        desc="Loken commands the forces of Ulduar, but not all serve him willingly. The Maiden of Grief has been ordered to destroy any who try reclaiming the Halls of Stone. She mourns turning on former allies, but fulfills her orders with violent purpose. Even her sorrows have been forged into weapons.",
        creatures = { {display=26657, file=607706, name="Maiden of Grief"} },
        loot = { {id=38615,pct=21.0,q=3,diff=6,name="Lightning-Charged Gloves"}, {id=38613,pct=29.0,q=3,diff=6,name="Chain of Fiery Orbs"}, {id=38618,pct=22.0,q=3,diff=6,name="Hammer of Grief"}, {id=38611,pct=29.0,q=3,diff=6,name="Ringlet of Repose"}, {id=38617,pct=22.0,q=3,diff=6,name="Woeful Band"}, {id=38614,pct=28.0,q=3,diff=6,name="Embrace of Sorrow"}, {id=38616,pct=21.0,q=3,diff=6,name="Maiden's Girdle"} },
        sections = {
          { id=7290, title="Pillar of Woe", parent=0, child=0, sib=7291, order=1, spell=0, icon="Interface\\icons\\spell_shadow_soulleech_3", flags=0, cdisp=0,
            body="The Maiden of Grief blasts an enemy, inflicting Shadow damage and additional Shadow damage every $50761t2 sec. for $50761d." },
          { id=7291, title="Shock of Sorrow", parent=0, child=0, sib=7292, order=2, spell=0, icon="Interface\\icons\\spell_brokenheart", flags=0, cdisp=0,
            body="The Maiden of Grief instantly shocks all players, inflicting Shadow damage and places them in a state of meditation that incapacitates them for $50760d. This effect breaks when the player takes damage." },
          { id=7292, title="Storm of Grief", parent=0, child=0, sib=7293, order=3, spell=0, icon="Interface\\icons\\spell_nature_callstorm", flags=0, cdisp=0,
            body="The Maiden of Grief creates a storm of shadow that lasts $50752d., blasting all players in a selected area for Shadow damage and inflicting additional Shadow damage every $50752t2 sec." },
          { id=7293, title="Parting Sorrow", parent=0, child=0, sib=0, order=4, spell=0, icon="Interface\\icons\\spell_shadow_manaburn", flags=2, cdisp=0,
            body="The Maiden of Grief hits a player with an anti-mana bolt. For each point of mana consumed by the bolt, the target takes $59723e1 Shadow damage." },
        },
      },
      { id=606, name="Tribunal of Ages", order=3,
        uiMapID=140, x=0.8456, y=0.7602, rootSection=7294,
        desc="Abedneum, Kaddrak, and Marnak make up the Tribunal of Ages, librarians for the titan discs that contain the ancient histories of Azeroth. The immobile constructs do not give up the titans' secrets easily, but adventurers such as the intrepid Brann Bronzebeard believe the reward is worth the risk.",
