        loot = { {id=37655,pct=16.0,q=3,diff=6,name="Mantle of the Tribunal"}, {id=37656,pct=16.0,q=3,diff=6,name="Raging Construct Bands"}, {id=35677,pct=25.0,q=3,diff=6,name="Cosmos Vestments"}, {id=35676,pct=26.0,q=3,diff=6,name="Constellation Leggings"}, {id=37654,pct=14.0,q=3,diff=6,name="Sabatons of the Ages"}, {id=35675,pct=24.0,q=3,diff=6,name="Linked Armor of the Sphere"}, {id=37653,pct=16.0,q=3,diff=6,name="Sword of Justice"} },
