      { id=607, name="Sjonnir the Ironshaper", order=4,
        uiMapID=140, x=0.4973, y=0.1373, rootSection=7313,
        desc="While some resisted Loken's corruption, Sjonnir the Ironshaper was eager to turn the Forge of Wills to a darker purpose. He considers his new creations vastly superior to the earthen, and will unleash them on any who defy Loken's will.",
        creatures = { {display=27483, file=607772, name="Sjonnir The Ironshaper"} },
        loot = { {id=37667,pct=18.0,q=4,diff=6,name="The Fleshshaper"}, {id=37657,pct=19.0,q=3,diff=6,name="Spark of Life"}, {id=37669,pct=18.0,q=4,diff=6,name="Leggings of the Stone Halls"}, {id=35678,pct=28.0,q=3,diff=6,name="Ironshaper's Legplates"}, {id=35679,pct=28.0,q=3,diff=6,name="Static Cowl"}, {id=37666,pct=19.0,q=3,diff=6,name="Boots of the Whirling Mist"}, {id=37670,pct=18.0,q=4,diff=6,name="Sjonnir's Girdle"}, {id=37668,pct=18.0,q=4,diff=6,name="Bands of the Stoneforge"}, {id=37660,pct=18.0,q=3,diff=6,name="Forge Ember"}, {id=37658,pct=19.0,q=3,diff=6,name="Sun-Emblazoned Chestplate"}, {id=35680,pct=29.0,q=3,diff=6,name="Amulet of Wills"} },
        sections = {
          { id=7313, title="Chain Lightning", parent=0, child=0, sib=7314, order=1, spell=0, icon="Interface\\icons\\spell_nature_chainlightning", flags=0, cdisp=0,
            body="Sjonnir the Ironshaper strikes a player with a lightning bolt that arcs to another nearby player. The spell affects up to $50830x1 targets, inflicting greater Nature damage to each successive target." },
          { id=7314, title="Lightning Shield", parent=0, child=0, sib=7315, order=2, spell=0, icon="Interface\\icons\\spell_nature_lightningshield", flags=0, cdisp=0,
            body="Sjonnir the Ironshaper surrounds himself with $50831n balls of lightning that have $50831h% chance of striking melee or ranged attackers with Nature damage. Each time the lightning shield strikes, a ball of lightning dissipates. Thus, the shield expires after $50831d. or after it has struck $50831n times." },
          { id=7315, title="Static Charge", parent=0, child=0, sib=7316, order=3, spell=0, icon="Interface\\icons\\spell_nature_lightningoverload", flags=0, cdisp=0,
            body="Sjonnir the Ironshaper afflicts a player with a static charge that periodically zaps its nearby allies and enemies for Nature damage. This effect lasts $50835d." },
          { id=7316, title="Lightning Ring", parent=0, child=0, sib=7319, order=4, spell=0, icon="Interface\\icons\\spell_nature_purge", flags=0, cdisp=0,
            body="Sjonnir the Ironshaper inflicts Nature damage to all players within $50841A1 yards and increases the Nature damage they take by $50841s2% for $50841d." },
          { id=7319, title="Frenzy", parent=0, child=0, sib=7317, order=5, spell=0, icon="Interface\\icons\\spell_shadow_unholyfrenzy", flags=0, cdisp=0,
            body="When Sjonnir the Ironshaper reaches 20% health remaining, he goes into a frenzy. Frenzy increases attack speed by $28747s2% and Physical damage done by $28747s1%." },
          { id=7317, title="Forged Iron Dwarf", parent=0, child=7323, sib=7318, order=6, spell=0, icon=0, flags=0, cdisp=25754,
            body="When engaged, Sjonnir the Ironshaper begins to summon Forged Iron Dwarf from the nearby forges." },
