  { id=278, name="Pit of Saron", isRaid=false, minLevel=70,
    mapID=658, loreFDID=608249, bgFDID=608171, buttonFDID=608210,
    desc="Agents of the Lich King have captured Alliance forces and put them to work in this frozen quarry. To disrupt this critical source of saronite used for the Scourge's war effort, Lady Jaina Proudmoore and her allies aim to free these captives and put down the leader of this operation, Scourgelord Tyrannus.",
    encounters = {
      { id=608, name="Forgemaster Garfrost", order=1,
        uiMapID=184, x=0.6803, y=0.5533, rootSection=34246,
        desc="Forgemaster Garfrost has forged saronite into some of the most deadly weapons of the Scourge. He fills the air with a sinster chill, and he loves nothing more than squashing foes with the ore he carries on his back.",
        creatures = { {display=137504, file=607603, name="Forgemaster Garfrost"} },
        loot = { {id=49801,pct=0,q=4,diff=6,name="Unspeakable Secret"}, {id=50234,pct=0,q=4,diff=6,name="Shoulderplates of Frozen Blood"}, {id=49806,pct=0,q=4,diff=6,name="Flayer's Black Belt"}, {id=49803,pct=0,q=4,diff=6,name="Ring of Carnelian and Bone"}, {id=49802,pct=0,q=4,diff=6,name="Garfrost's Two-Ton Hammer"}, {id=50227,pct=0,q=4,diff=6,name="Surgeon's Needle"}, {id=50233,pct=0,q=4,diff=6,name="Spurned Val'kyr Shoulderguards"}, {id=49804,pct=0,q=4,diff=6,name="Polished Mirror Helm"}, {id=50230,pct=0,q=4,diff=6,name="Malykriss Vambraces"}, {id=50228,pct=0,q=4,diff=6,name="Barbed Ymirheim Choker"}, {id=50229,pct=0,q=4,diff=6,name="Legguards of the Frosty Depths"}, {id=49805,pct=0,q=4,diff=6,name="Ice-Steeped Sandals"} },
        sections = {
          { id=34246, title="Overview", parent=0, child=34247, sib=34250, order=1, spell=0, icon=0, flags=0, cdisp=0,
            body="Forgemaster Garfrost |cFF2959D3|Hspell:1261299|h[Throws Saronite]|h|r at players, then follows up with |cFF2959D3|Hspell:1261546|h[Orebreaker]|h|r. Occasionally, he lets loose a mighty |cFF2959D3|Hspell:1261847|h[Cryostomp]|h|r, increasing |cFF2959D3|Hspell:1261806|h[Siphoning Chill's]|h|r danger.\n\nUpon reaching 100 energy, Garfrost activates a |cFF2959D3|Hspell:1262029|h[Glacial Overload]|h|r from his closest forge." },
          { id=34247, title="Damage Dealers", parent=34246, child=0, sib=34248, order=2, spell=0, icon=0, flags=0, cdisp=0,
            body="$bullet;Garfrost |cFF2959D3|Hspell:1261299|h[Throws Saronite]|h|r at targeted players.\n$bullet;Saronite ore offers protection from |cFF2959D3|Hspell:1262029|h[Glacial Overload]|h|r." },
          { id=34248, title="Healer", parent=34246, child=0, sib=34249, order=3, spell=0, icon=0, flags=0, cdisp=0,
            body="$bullet;|cFF2959D3|Hspell:1261847|h[Cryostomp]|h|r increases the danger of |cFF2959D3|Hspell:1261806|h[Siphoning Chill]|h|r.\n$bullet;Saronite ore offers protection from |cFF2959D3|Hspell:1262029|h[Glacial Overload]|h|r." },
          { id=34249, title="Tank", parent=34246, child=0, sib=0, order=4, spell=0, icon=0, flags=0, cdisp=0,
            body="$bullet;|cFF2959D3|Hspell:1261546|h[Orebreaker]|h|r does not stun its target if it strikes saronite ore.\n$bullet;Saronite ore offers protection from |cFF2959D3|Hspell:1262029|h[Glacial Overload]|h|r." },
          { id=34250, title="Section 9", parent=0, child=0, sib=34251, order=5, spell=1262029, icon=0, flags=0, cdisp=0,
            body="" },
          { id=34251, title="", parent=0, child=34252, sib=34253, order=6, spell=1261299, icon=0, flags=1, cdisp=0,
            body="" },
