      { id=609, name="Ick and Krick", order=2,
        uiMapID=184, x=0.4754, y=0.3975, rootSection=34357,
        desc="The diminutive necromancer Krick oversees the contruction of horrific constructs within the Pit of Saron. Krick wears his foes down with dark magic and then commands the ghastly Ick to rip them into pieces.",
        creatures = { {display=137499, file=7524258, name="Krick"}, {display=137500, file=0, name="Ick"}, {display=138601, file=0, name="Shade of Krick"} },
        loot = { {id=50262,pct=0,q=4,diff=6,name="Felglacier Bolter"}, {id=50263,pct=0,q=4,diff=6,name="Braid of Salt and Fire"}, {id=50266,pct=0,q=4,diff=6,name="Ancient Polar Bear Hide"}, {id=50235,pct=0,q=4,diff=6,name="Ick's Rotting Thumb"}, {id=50264,pct=0,q=4,diff=6,name="Chewed Leather Wristguards"}, {id=50265,pct=0,q=4,diff=6,name="Blackened Ghoul Skin Leggings"}, {id=49808,pct=0,q=4,diff=6,name="Bent Gold Belt"}, {id=49810,pct=0,q=4,diff=6,name="Scabrous Zombie Leather Belt"}, {id=49809,pct=0,q=4,diff=6,name="Wristguards of Subterranean Moss"}, {id=49812,pct=0,q=4,diff=6,name="Purloined Wedding Ring"}, {id=49807,pct=0,q=4,diff=6,name="Krick's Beetle Stabber"}, {id=49811,pct=0,q=4,diff=6,name="Black Dragonskin Breeches"} },
        sections = {
          { id=34357, title="Overview", parent=0, child=34358, sib=35179, order=1, spell=0, icon=0, flags=0, cdisp=0,
            body="Krick and his construct, Ick, battle players simultaneously. |cFF2959D3|Hspell:1264259|h[Shades of Krick]|h|r channel |cFF2959D3|Hspell:1264186|h[Shadowbind]|h|r while Ick attacks with |cFF2959D3|Hspell:1264336|h[Plague Expulsion]|h|r and |cFF2959D3|Hspell:1264287|h[Blight Smash]|h|r.\n\nUpon reaching 100 energy, Krick yells, \"|cFF2959D3|Hspell:1264363|h[Get 'Em, Ick!]|h|r,\" commanding his monstrous minion to attack specific players." },
          { id=34358, title="Damage Dealers", parent=34357, child=0, sib=34359, order=2, spell=0, icon=0, flags=0, cdisp=0,
            body="$bullet;|cFF2959D3|Hspell:1264259|h[Shades of Krick]|h|r explode for significant damage if not defeated quickly.\n$bullet;|cFF2959D3|Hspell:1264186|h[Shadowbind]|h|r and |cFF2959D3|Hspell:1278893|h[Death Bolt]|h|r inflict significant harm unless stopped.\n$bullet;Krick's |cFF2959D3|Hspell:1264363|h[Get 'Em, Ick!]|h|r compels Ick to fixate a player, ignoring others at all costs." },
          { id=34359, title="Healer", parent=34357, child=0, sib=34360, order=3, spell=0, icon=0, flags=0, cdisp=0,
            body="$bullet;|cFF2959D3|Hspell:1264027|h[Shade Shift]|h|r inflicts significant damage to all players.\n$bullet;|cFF2959D3|Hspell:1264259|h[Shades of Krick]|h|r channel |cFF2959D3|Hspell:1264186|h[Shadowbind]|h|r, inflicting intense periodic damage.\n$bullet;Krick's |cFF2959D3|Hspell:1264363|h[Get 'Em, Ick!]|h|r compels Ick to fixate a player, ignoring others at all costs." },
          { id=34360, title="Tank", parent=34357, child=0, sib=0, order=4, spell=0, icon=0, flags=0, cdisp=0,
            body="$bullet;Ick's |cFF2959D3|Hspell:1264287|h[Blight Smash]|h|r inflicts significant damage to his primary target.\n$bullet;|cFF2959D3|Hspell:1264186|h[Shadowbind]|h|r and |cFF2959D3|Hspell:1278893|h[Death Bolt]|h|r inflict significant harm unless stopped.\n$bullet;|cFF2959D3|Hspell:1264259|h[Shades of Krick]|h|r explode for significant damage if not defeated quickly." },
          { id=35179, title="Section 23", parent=0, child=0, sib=34361, order=5, spell=1264192, icon=0, flags=1, cdisp=0,
            body="" },
          { id=34361, title="Krick", parent=0, child=34362, sib=34367, order=6, spell=0, icon=0, flags=1, cdisp=137499,
            body="" },
