      { id=610, name="Scourgelord Tyrannus", order=3,
        uiMapID=184, x=0.4413, y=0.2664, rootSection=34313,
        desc="The death knight Tyrannus was promoted to Scourgelord after slaying the giant Garfrost. His power and ruthlessness alongside his frost wyrm, Rimefang, make him the perfect guardian for the Pit of Saron and the entrance to the Halls of Reflection.",
        creatures = { {display=137505, file=7526001, name="Scourgelord Tyrannus"}, {display=31154, file=0, name="Rimefang"}, {display=138341, file=0, name="Scourge Plaguespreader"}, {display=138343, file=0, name="Rotling"} },
        loot = { {id=50273,pct=0,q=4,diff=6,name="Engraved Gargoyle Femur"}, {id=50268,pct=0,q=4,diff=6,name="Rimefang's Claw"}, {id=50259,pct=0,q=4,diff=6,name="Nevermelting Ice Crystal"}, {id=50272,pct=0,q=4,diff=6,name="Frost Wyrm Ribcage"}, {id=50286,pct=0,q=4,diff=6,name="Prelate's Snowshoes"}, {id=50271,pct=0,q=4,diff=6,name="Band of Stained Souls"}, {id=50270,pct=0,q=4,diff=6,name="Belt of Rotted Fingernails"}, {id=50267,pct=0,q=4,diff=6,name="Tyrannical Beheader"}, {id=50284,pct=0,q=4,diff=6,name="Rusty Frozen Fingerguards"}, {id=50283,pct=0,q=4,diff=6,name="Mudslide Boots"}, {id=50285,pct=0,q=4,diff=6,name="Icebound Bronze Cuirass"}, {id=50269,pct=0,q=4,diff=6,name="Fleshwerk Leggings"}, {id=49818,pct=0,q=4,diff=6,name="Painfully Sharp Choker"}, {id=49826,pct=0,q=4,diff=6,name="Shroud of Rime"}, {id=49816,pct=0,q=4,diff=6,name="Scourgelord's Frigid Chestplate"}, {id=49813,pct=0,q=4,diff=6,name="Rimebane Rifle"}, {id=49822,pct=0,q=4,diff=6,name="Rimewoven Silks"}, {id=49819,pct=0,q=4,diff=6,name="Skeleton Lord's Cranium"}, {id=49820,pct=0,q=4,diff=6,name="Gondria's Spectral Bracer"}, {id=49825,pct=0,q=4,diff=6,name="Palebone Robes"}, {id=49817,pct=0,q=4,diff=6,name="Shaggy Wyrmleather Leggings"}, {id=49823,pct=0,q=4,diff=6,name="Cloak of the Fallen Cardinal"}, {id=49821,pct=0,q=4,diff=6,name="Protector of Frigid Souls"}, {id=49824,pct=0,q=4,diff=6,name="Horns of the Spurned Val'kyr"} },
        sections = {
          { id=34313, title="Overview", parent=0, child=35183, sib=34317, order=1, spell=0, icon=0, flags=0, cdisp=0,
            body="Scourgelord Tyrannus opens his assault with |cFF2959D3|Hspell:1276648|h[Bone Infusion]|h|r while his dragon, Rimefang, attacks from the air with |cFF2959D3|Hspell:1262745|h[Rime Blast]|h|r. While building his power, Scourgelord Tyrannus unleashes |cFF2959D3|Hspell:1263756|h[Death's Grasp]|h|r and |cFF2959D3|Hspell:1262582|h[Scourgelord's Brand]|h|r.\n\nUpon reaching 100 energy, he raises undead minions with |cFF2959D3|Hspell:1263406|h[Army of the Dead]|h|r." },
          { id=35183, title="Damage Dealers", parent=34313, child=0, sib=34314, order=2, spell=0, icon=0, flags=2, cdisp=0,
            body="$bullet;Scourgelord Tyrannus's |cFF2959D3|Hspell:1263406|h[Army of the Dead]|h|r summons a swarm of minions.\n$bullet;Rimefang's |cFF2959D3|Hspell:1262745|h[Rime Blast]|h|r freezes any |cFF2959D3|Hspell:1276357|h[Bone Piles]|h|r it impacts.\n$bullet;Scourgelord Tyrannus's |cFF2959D3|Hspell:1263756|h[Death's Grasp]|h|r and Rimefang's |cFF2959D3|Hspell:1276948|h[Ice Barrage]|h|r inflict significant damage at targeted locations." },
          { id=34314, title="Damage Dealers", parent=34313, child=0, sib=35184, order=3, spell=0, icon=0, flags=2, cdisp=0,
            body="$bullet;Scourgelord Tyrannus's |cFF2959D3|Hspell:1263406|h[Army of the Dead]|h|r summons a swarm of minions.\n$bullet;Rimefang's |cFF2959D3|Hspell:1262745|h[Rime Blast]|h|r freezes any |cFF2959D3|Hspell:1276357|h[Bone Piles]|h|r or |cFF2959D3|Hspell:1276391|h[Infused Bone Piles]|h|r it impacts.\n$bullet;Scourgelord Tyrannus's |cFF2959D3|Hspell:1276648|h[Bone Infusion]|h|r empowers some |cFF2959D3|Hspell:1276357|h[Bone Piles]|h|r." },
          { id=35184, title="Healer", parent=34313, child=0, sib=34315, order=4, spell=0, icon=0, flags=2, cdisp=0,
            body="$bullet;|cFF2959D3|Hspell:1276648|h[Bone Infusion]|h|r, |cFF2959D3|Hspell:1262745|h[Rime Blast]|h|r, and |cFF2959D3|Hspell:1262739|h[Frost Spit]|h|r inflict significant damage to players.\n$bullet;Rimefang's |cFF2959D3|Hspell:1262745|h[Rime Blast]|h|r freezes any |cFF2959D3|Hspell:1276357|h[Bone Piles]|h|r it impacts.\n$bullet;Scourgelord Tyrannus's |cFF2959D3|Hspell:1263406|h[Army of the Dead]|h|r summons minions that inflict significant damage to players." },
          { id=34315, title="Healer", parent=34313, child=0, sib=35185, order=5, spell=0, icon=0, flags=2, cdisp=0,
            body="$bullet;|cFF2959D3|Hspell:1276648|h[Bone Infusion]|h|r, |cFF2959D3|Hspell:1262745|h[Rime Blast]|h|r, and |cFF2959D3|Hspell:1262739|h[Frost Spit]|h|r inflict significant damage to players.\n$bullet;Rimefang's |cFF2959D3|Hspell:1262745|h[Rime Blast]|h|r freezes any |cFF2959D3|Hspell:1276357|h[Bone Piles]|h|r or |cFF2959D3|Hspell:1276391|h[Infused Bone Piles]|h|r it impacts.\n$bullet;Scourgelord Tyrannus's |cFF2959D3|Hspell:1263406|h[Army of the Dead]|h|r summons minions that inflict significant damage to players." },
          { id=35185, title="Tank", parent=34313, child=0, sib=34316, order=6, spell=0, icon=0, flags=2, cdisp=0,
            body="$bullet;|cFF2959D3|Hspell:1262582|h[Scourgelord's Brand]|h|r increases the damage of |cFF2959D3|Hspell:1263671|h[Scourgelord's Reckoning]|h|r.\n$bullet;Scourgelord Tyrannus's |cFF2959D3|Hspell:1263406|h[Army of the Dead]|h|r summons a swarm of minions.\n$bullet;Scourgelord Tyrannus's |cFF2959D3|Hspell:1263756|h[Death's Grasp]|h|r and Rimefang's |cFF2959D3|Hspell:1276948|h[Ice Barrage]|h|r inflict significant damage at targeted locations." },
          { id=34316, title="Tank", parent=34313, child=0, sib=0, order=7, spell=0, icon=0, flags=2, cdisp=0,
            body="$bullet;|cFF2959D3|Hspell:1262582|h[Scourgelord's Brand]|h|r increases the damage of |cFF2959D3|Hspell:1263671|h[Scourgelord's Reckoning]|h|r.\n$bullet;Scourgelord Tyrannus's |cFF2959D3|Hspell:1263406|h[Army of the Dead]|h|r summons a swarm of minions.\n$bullet;Scourgelord Tyrannus's |cFF2959D3|Hspell:1276648|h[Bone Infusion]|h|r empowers some |cFF2959D3|Hspell:1276357|h[Bone Piles]|h|r." },
