  { id=279, name="The Culling of Stratholme", isRaid=false, minLevel=70,
    mapID=595, loreFDID=608258, bgFDID=608180, buttonFDID=608219,
    desc="Deep within the Caverns of Time, the brooding dragon Nozdormu has awakened. Since the world was young, the bronze dragonflight has safeguarded the winding labyrinth, monitoring the shifting timeways to ensure that the delicate balance of time is upheld.",
    encounters = {
      { id=611, name="Meathook", order=1,
        uiMapID=131, x=0.5669, y=0.5922, rootSection=7361,
        desc="Since Prince Arthas first encountered the Scourge abominations, they have become even more menacing. Meathook has grown stronger, more toxic and more agile than the others. Smarter was never the goal of the necromancers who created Meathook, but it only takes a base cunning to do what he does best.",
        creatures = { {display=26579, file=607711, name="Meathook"} },
        loot = { {id=37081,pct=22.0,q=3,diff=6,name="Meathook's Slicer"}, {id=37083,pct=23.0,q=3,diff=6,name="Kilt of Sewn Flesh"}, {id=37679,pct=21.0,q=3,diff=6,name="Spaulders of the Abomination"}, {id=37675,pct=23.0,q=3,diff=6,name="Legplates of Steel Implants"}, {id=37082,pct=22.0,q=3,diff=6,name="Slaughterhouse Sabatons"}, {id=37079,pct=23.0,q=3,diff=6,name="Enchanted Wire Stitching"}, {id=37678,pct=22.0,q=3,diff=6,name="Bile-Cured Gloves"}, {id=37680,pct=22.0,q=3,diff=6,name="Belt of Unified Souls"} },
        sections = {
          { id=7361, title="Constricting Chains", parent=0, child=0, sib=7362, order=1, spell=0, icon="Interface\\icons\\inv_belt_18", flags=0, cdisp=0,
            body="Meathook encases a player in chains, inflicting Physical damage every $52696t1 sec. and stunning the target for $52696d." },
          { id=7362, title="Disease Explusion", parent=0, child=0, sib=7363, order=2, spell=0, icon="Interface\\icons\\spell_nature_elementalshields", flags=0, cdisp=0,
            body="Meathook belches out a cloud of disease, inflicting Nature damage and interrupting the spell casting of all players within $52666A1 yards for $52666d." },
          { id=7363, title="Frenzy", parent=0, child=0, sib=0, order=3, spell=0, icon="Interface\\icons\\spell_shadow_unholyfrenzy", flags=2, cdisp=0,
            body="Meathook goes into a frenzy, increasing Physical damage done by $58841s2% for $58841d. This effect stacks up to $58841u times." },
        },
      },
      { id=612, name="Salramm the Fleshcrafter", order=2,
        uiMapID=131, x=0.5915, y=0.4016, rootSection=7365,
        desc="Salramm the Fleshcrafter was one of the first necromancers trained in the halls beneath Scholomance. He saw the test subjects, and occasional fellow students, as little more than a collection of interesting parts for his work. Now he has the entire population of Stratholme for his experiments... along with any interlopers who try to stop him.",
        creatures = { {display=26581, file=607763, name="Salramm the Fleshcrafter"} },
        loot = { {id=37088,pct=22.0,q=3,diff=6,name="Spiked Metal Cilice"}, {id=37681,pct=22.0,q=3,diff=6,name="Gavel of the Fleshcrafter"}, {id=37682,pct=22.0,q=3,diff=6,name="Bindings of Dark Will"}, {id=37683,pct=22.0,q=3,diff=6,name="Necromancer's Amulet"}, {id=37084,pct=22.0,q=3,diff=6,name="Flowing Cloak of Command"}, {id=37684,pct=22.0,q=3,diff=6,name="Forgotten Shadow Hood"}, {id=37086,pct=23.0,q=3,diff=6,name="Tome of Salramm"}, {id=37095,pct=23.0,q=3,diff=6,name="Waistband of the Thuzadin"} },
        sections = {
          { id=7365, title="Shadow Bolt", parent=0, child=0, sib=7366, order=1, spell=0, icon="Interface\\icons\\spell_shadow_shadowbolt", flags=0, cdisp=0,
            body="Salramm the Fleshcrafter hurls a bolt of dark magic at a player, inflicting Shadow damage." },
          { id=7366, title="Steal Flesh", parent=0, child=0, sib=7367, order=2, spell=0, icon="Interface\\icons\\spell_shadow_lifedrain02", flags=0, cdisp=0,
            body="Salramm the Fleshcrafter steals the flesh of a player, reducing the player's damage done by $52711s1% and increasing his by $52712s1%." },
          { id=7367, title="Summon Ghouls", parent=0, child=0, sib=7368, order=3, spell=0, icon="Interface\\icons\\spell_shadow_raisedead", flags=0, cdisp=0,
            body="Salramm the Fleshcrafter summons two Ghoul Minions." },
          { id=7368, title="Explode Ghoul", parent=0, child=0, sib=7369, order=4, spell=0, icon="Interface\\icons\\spell_shadow_corpseexplode", flags=0, cdisp=0,
            body="Salramm the Fleshcrafter explodes a nearby ghoul, inflicting Fire damage to all players within $52480a3 yds." },
          { id=7369, title="Curse of Twisted Flesh", parent=0, child=0, sib=0, order=5, spell=0, icon="Interface\\icons\\spell_shadow_painandsuffering", flags=2, cdisp=0,
            body="Salramm the Fleshcrafter curses a player, reducing their maximum health by $58845s2%, and inflicts $58845s1 Shadow damage every $58845t1 sec. for $58845d." },
        },
      },
      { id=613, name="Chrono-Lord Epoch", order=3,
        uiMapID=131, x=0.6585, y=0.2582, rootSection=7371,
        desc="The infinite dragonflight often tries subtle methods to manipulate the timeways, but if that fails they can send an assassin to deal with Arthas directly. While little is known about the agents of the infinite dragonflight, Epoch displays a dangerous mastery of time that makes him a deadly obstacle to Arthas's future.",
        creatures = { {display=26580, file=607567, name="Chrono-Lord Epoch"} },
        loot = { {id=37687,pct=23.0,q=3,diff=6,name="Gloves of Distorted Time"}, {id=37105,pct=24.0,q=3,diff=6,name="Treads of Altered History"}, {id=37099,pct=22.0,q=3,diff=6,name="Sempiternal Staff"}, {id=37686,pct=23.0,q=3,diff=6,name="Cracked Epoch Grasps"}, {id=37106,pct=23.0,q=3,diff=6,name="Ouroboros Belt"}, {id=37096,pct=22.0,q=3,diff=6,name="Necklace of the Chrono-Lord"}, {id=37685,pct=23.0,q=3,diff=6,name="Mobius Band"}, {id=37688,pct=23.0,q=3,diff=6,name="Legplates of the Infinite Drakonid"} },
        sections = {
          { id=7371, title="Time Warp", parent=0, child=0, sib=7755, order=1, spell=0, icon="Interface\\icons\\inv_qiraj_jewelblessed", flags=0, cdisp=0,
            body="Chrono-Lord Epoch slows time, reducing melee, casting and movement speed of all players by $52766s1% for $52766d." },
          { id=7755, title="Time Step", parent=0, child=0, sib=7372, order=2, spell=0, icon="Interface\\icons\\ability_warrior_charge", flags=0, cdisp=0,
            body="Chrono-Lord Epoch steps through time, charging a random player and inflicting Physical damage to them." },
          { id=7372, title="Wounding Strike", parent=0, child=0, sib=7373, order=3, spell=0, icon="Interface\\icons\\ability_warrior_trauma", flags=0, cdisp=0,
            body="Chrono-Lord Epoch savagely wounds a player, inflicting Physical damage, reducing healing effects by $52771s2%, and inflicting Physical damage every $52771t3 sec. for $52771d." },
          { id=7373, title="Curse of Exertion", parent=0, child=0, sib=7374, order=4, spell=0, icon="Interface\\icons\\spell_arcane_focusedpower", flags=0, cdisp=0,
            body="Chrono-Lord Epoch increases a player's cost of spells and abilities by $52772s1% for $52772d." },
          { id=7374, title="Time Stop", parent=0, child=0, sib=0, order=5, spell=0, icon="Interface\\icons\\spell_arcane_arcane01", flags=2, cdisp=0,
            body="Chrono-Lord Epoch stops time in a for $58848d., stunning all players." },
        },
      },
      { id=614, name="Mal'Ganis", order=4,
        uiMapID=131, x=0.3251, y=0.459, rootSection=7375,
        desc="The destiny of Mal'Ganis has already been written. Arthas's hatred for the dreadlord will cause the prince to travel to Northrend and take up Frostmourne. But this will only happen if Mal'Ganis finds him worthy. To prove his worthiness and begin down his path to becoming the Lich King, Arthas must survive Mal'Ganis's onslaught.",
        creatures = { {display=26582, file=607708, name="Mal'Ganis"} },
