        uiMapID=183, x=0.4358, y=0.4959, rootSection=7380,
        desc="Bronjahm has served the Cult of the Damned from the early days. Kel'Thuzad himself taught Bronjahm the value of souls and how to grind them down to fuel the engines of the Scourge. He can corrupt the souls of his foes and tear them out piece by piece, making him the ideal guardian for the Lich King's Forge of Souls.",
        creatures = { {display=30226, file=607559, name="Bronjahm"} },
        loot = { {id=50193,pct=0,q=4,diff=6,name="Very Fashionable Shoulders"}, {id=50194,pct=0,q=4,diff=6,name="Weeping Gauntlets"}, {id=50196,pct=0,q=4,diff=6,name="Love's Prisoner"}, {id=50197,pct=0,q=4,diff=6,name="Eyes of Bewilderment"}, {id=49783,pct=0,q=4,diff=6,name="Lucky Old Sun"}, {id=49784,pct=0,q=4,diff=6,name="Minister's Number One Legplates"}, {id=49785,pct=0,q=4,diff=6,name="Bewildering Shoulderpads"}, {id=49786,pct=0,q=4,diff=6,name="Robes of the Cheating Heart"}, {id=49787,pct=0,q=4,diff=6,name="Seven Stormy Mornings"}, {id=49788,pct=0,q=4,diff=6,name="Cold Sweat Grips"}, {id=50316,pct=0,q=4,diff=0,name="Papa's Brand New Bag"}, {id=50317,pct=0,q=4,diff=0,name="Papa's New Bag"}, {id=50191,pct=0,q=4,diff=6,name="Nighttime"} },
