      { id=616, name="Devourer of Souls", order=2,
        uiMapID=183, x=0.4344, y=0.1209, rootSection=7387,
        desc="The dark industries Bronjahm carries out in the Forge of Souls produce tortured, fragmented spirits. To prevent their escape, and use every scrap of the damned, the Lich King created the Devourer of Souls. The Devourer of Souls hunts and consumes the stray spirits, and slowly breaks them down within its terrible form. The consumed souls are driven mad with anguish and suffering, but the Devourer's hunger is never sated.",
        creatures = { {display=30148, file=607585, name="Devourer of Souls"} },
