      { id=619, name="Anomalus", order=3,
        uiMapID=129, x=0.6202, y=0.2213, rootSection=7405,
        desc="Directing so much of Azeroth's arcane energy through the Nexus has created tears in reality. As Malygos's forces try to drive back invading creatures, the chaotic arcane power has taken form as Anomalus. If the creature is not stopped, it will unmake everything it can touch.",
        creatures = { {display=26259, file=607540, name="Anomalus"} },
        loot = { {id=37150,pct=22.0,q=3,diff=6,name="Rift Striders"}, {id=37144,pct=22.0,q=3,diff=6,name="Hauberk of the Arcane Wraith"}, {id=35598,pct=29.0,q=3,diff=6,name="Tome of the Lore Keepers"}, {id=37149,pct=21.0,q=3,diff=6,name="Helm of Anomalus"}, {id=37141,pct=21.0,q=3,diff=6,name="Amulet of Dazzling Light"}, {id=35599,pct=31.0,q=3,diff=6,name="Gauntlets of Serpent Scales"}, {id=35600,pct=29.0,q=3,diff=6,name="Cleated Ice Boots"} },
