          { id=7409, title="Summon Crazed Mana-Wraith", parent=7408, child=0, sib=7410, order=5, spell=0, icon="Interface\\icons\\spell_arcane_prismaticcloak", flags=0, cdisp=0,
            body="Chaotic Rifts continuously summon Crazed Mana-Wraith until they are destroyed." },
          { id=7410, title="Chaotic Energy Burst", parent=7408, child=0, sib=0, order=6, spell=0, icon="Interface\\icons\\spell_arcane_arcane03", flags=0, cdisp=0,
