      { id=620, name="Ormorok the Tree-Shaper", order=4,
        uiMapID=129, x=0.5628, y=0.7275, rootSection=7416,
        desc="The incredible arcane energies of the Nexus have transformed the Singing Gardens and its guardians. Ormorok's simple mind has become obsessed with the energies transforming him. For those who would interrupt his contemplations he has few words, but a mountain of violence.",
        creatures = { {display=26298, file=607735, name="Ormorok the Tree-Shaper"} },
