  { id=282, name="The Oculus", isRaid=false, minLevel=70,
    mapID=578, loreFDID=608261, bgFDID=608183, buttonFDID=608222,
    desc="In order to reestablish his dominance over magic, the blue Dragon Aspect, Malygos, has launched a ruthless campaign to sever the link between mortals and the arcane energies coursing through Azeroth. To this end, his blue dragonflight is redirecting the ley lines of the world to the Nexus, Malygos' towering lair.",
    encounters = {
      { id=622, name="Drakos the Interrogator", order=1,
        uiMapID=143, x=0.4918, y=0.7623, rootSection=7437,
        desc="Those who have broken Malygos's law may find themselves under the claws of Drakos. After securing Keristrasza in the Nexus, Drakos returned to the Oculus to collect his newer prisoners, other drakes who ran afoul of Malygos. He makes no claims of rehabilitation and he uses no metaphors. His prisoners are here to be punished, and there is no escape.",
        creatures = { {display=27032, file=607590, name="Drakos the Interrogator"} },
        loot = { {id=36945,pct=21.0,q=3,diff=6,name="Verdisa's Cuffs of Dreaming"}, {id=36946,pct=23.0,q=3,diff=6,name="Runic Cage Chestpiece"}, {id=36943,pct=21.0,q=3,diff=6,name="Timeless Beads of Eternos"}, {id=37256,pct=23.0,q=3,diff=6,name="Scaled Armor of Drakos"}, {id=37255,pct=23.0,q=3,diff=6,name="The Interrogator"}, {id=37257,pct=23.0,q=3,diff=6,name="Band of Torture"}, {id=37258,pct=22.0,q=3,diff=6,name="Drakewing Raiments"}, {id=36944,pct=25.0,q=3,diff=6,name="Lifeblade of Belgaristrasz"} },
        sections = {
          { id=7437, title="Thundering Stomp", parent=0, child=0, sib=7438, order=1, spell=0, icon="Interface\\icons\\ability_warstomp", flags=0, cdisp=0,
            body="Drakos the Interrogator stomps the ground, inflicting Physical damage to all players, knocking them into the air." },
          { id=7438, title="Summon Unstable Sphere", parent=0, child=0, sib=7439, order=2, spell=0, icon="Interface\\icons\\spell_frost_wisp", flags=0, cdisp=0,
            body="Drakos the Interrogator periodically summons Unstable Spheres which explode after 20 seconds, inflicting Arcane damage to all players within $50759A1 yards." },
          { id=7439, title="Magic Pull", parent=0, child=0, sib=0, order=3, spell=0, icon="Interface\\icons\\spell_arcane_portaldarnassus", flags=0, cdisp=0,
            body="Drakos the Interrogator teleports all players to him." },
        },
      },
      { id=623, name="Varos Cloudstrider", order=2,
        uiMapID=144, x=0.4617, y=0.1926, rootSection=7440,
        desc="Varos Cloudstrider has coordinated brutal attacks against the Wyrmrest Accord since the beginning of the Nexus War. He was recalled to guard the Oculus, and he has already prepared his captains and drakes. Varos has also tapped the power coursing through the Oculus itself to bolster his defense.",
        creatures = { {display=27033, file=607802, name="Varos Cloudstrider"} },
        loot = { {id=37262,pct=21.0,q=3,diff=6,name="Azure Ringmail Leggings"}, {id=37260,pct=21.0,q=3,diff=6,name="Cloudstrider's Waraxe"}, {id=37261,pct=22.0,q=3,diff=6,name="Gloves of Radiant Light"}, {id=36948,pct=22.0,q=3,diff=6,name="Horned Helm of Varos"}, {id=37263,pct=21.0,q=3,diff=6,name="Legplates of the Oculus Guardian"}, {id=36947,pct=21.0,q=3,diff=6,name="Centrifuge Core Cloak"}, {id=36949,pct=21.0,q=3,diff=6,name="Gloves of the Azure-Lord"}, {id=36950,pct=23.0,q=3,diff=6,name="Wing Commander's Breastplate"} },
