      { id=624, name="Mage-Lord Urom", order=3,
        uiMapID=145, x=0.7077, y=0.2746, rootSection=7445,
        desc="Urom has abandoned the Kirin Tor and pledged his loyalty to Malygos, who was more than happy to receive him. The turncoat mage is an invaluable asset for the blue dragons. He knows the Kirin Tor's strengths and weaknesses. He knows how they think. And he will use that knowledge to destroy them.",
        creatures = { {display=25010, file=607702, name="Mage-Lord Urom"} },
        loot = { {id=37195,pct=20.0,q=3,diff=6,name="Band of Enchanted Growth"}, {id=36953,pct=21.0,q=3,diff=6,name="Spaulders of Skillful Maneuvers"}, {id=36954,pct=21.0,q=3,diff=6,name="The Conjurer's Slippers"}, {id=37288,pct=18.0,q=3,diff=6,name="Catalytic Bands"}, {id=37264,pct=20.0,q=3,diff=6,name="Pendulum of Telluric Currents"}, {id=37289,pct=18.0,q=3,diff=6,name="Sash of Phantasmal Images"}, {id=36952,pct=18.0,q=3,diff=6,name="Girdle of Obscuring"}, {id=36951,pct=20.0,q=3,diff=6,name="Sidestepping Handguards"} },
        sections = {
          { id=7445, title="Frostbomb", parent=0, child=0, sib=7446, order=1, spell=0, icon="Interface\\icons\\spell_frost_frozencore", flags=0, cdisp=0,
            body="Mage-Lord Urom launches a Frostbomb that inflicts Frost damage and freezes the ground, inflicting periodic damage and slowing the movement speed of players in an area." },
          { id=7446, title="Time Bomb", parent=0, child=0, sib=7447, order=2, spell=0, icon=609811, flags=0, cdisp=0,
            body="Mage-Lord Urom inflicts Arcane damage to a random player, placing a time bomb in them.  After $51121t2 sec. the bomb explodes, inflicting Arcane damage to all players within $51132A1 yards equal to the amount of health missing from the player with Time Bomb." },
          { id=7447, title="Empowered Arcane Explosion", parent=0, child=0, sib=0, order=3, spell=0, icon="Interface\\icons\\spell_nature_wispsplode", flags=0, cdisp=0,
