  { id=283, name="The Violet Hold", isRaid=false, minLevel=70,
    mapID=608, loreFDID=608312, bgFDID=608189, buttonFDID=608228,
    desc="Among the ornate spires and enchanted streets of Dalaran, a dark presence stirs within the mighty walls of the Violet Hold. Long used to restrain threats to the city, the tower holds row upon row of deadly inmates, and it has been diligently watched over by the Kirin Tor. However, a sudden assault has tested the integrity of the hold, putting at risk the safety of everyone outside the prison's walls.",
    encounters = {
      { id=626, name="Erekem", order=1,
        uiMapID=168, x=0.276, y=0.623, rootSection=7457,
        desc="The Violet Hold's inmates include the most notorious of Outland's criminals, and Erekem is no exception. The Kirin Tor thwarted his plot to assassinate the Council of Six, but now the blue dragons have recruited this insidious arakkoa to achieve a more ambitious feat: wiping out every mage in Dalaran.",
        creatures = { {display=27488, file=607597, name="Erekem"} },
        loot = { {id=43406,pct=29.0,q=3,diff=6,name="Cloak of the Gushing Wound"}, {id=43375,pct=45.0,q=3,diff=6,name="Trousers of the Arakkoa"}, {id=43405,pct=29.0,q=3,diff=6,name="Sabatons of Erekem"}, {id=43363,pct=43.0,q=3,diff=6,name="Screeching Cape"}, {id=43407,pct=30.0,q=3,diff=6,name="Stormstrike Mace"} },
        sections = {
          { id=7457, title="Earth Shield", parent=0, child=0, sib=7458, order=1, spell=0, icon="Interface\\icons\\spell_nature_skinofearth", flags=0, cdisp=0,
            body="Erekem protects an ally with an earthen shield, causing melee attacks to heal them.  The shield lasts until $54479n charges are consumed or $54479d." },
          { id=7458, title="Chain Heal", parent=0, child=0, sib=7459, order=2, spell=0, icon="Interface\\icons\\spell_nature_healingwavegreater", flags=0, cdisp=0,
            body="Erekem infuses a wounded ally with healing energy that spreads to another nearby ally. The spell affects up to $54481x1 targets." },
          { id=7459, title="Bloodlust", parent=0, child=0, sib=7460, order=3, spell=0, icon="Interface\\icons\\spell_nature_bloodlust", flags=0, cdisp=0,
            body="Erekem increases melee, ranged, and spell casting speed by $54516s1% for all of his allies. This effect lasts $54516d." },
          { id=7460, title="Lightning Bolt", parent=0, child=0, sib=7461, order=4, spell=0, icon="Interface\\icons\\spell_nature_lightning", flags=0, cdisp=0,
            body="Erekem blasts a player with lightning, inflicting Nature damage." },
          { id=7461, title="Break Bonds", parent=0, child=0, sib=7462, order=5, spell=0, icon="Interface\\icons\\spell_nature_strength", flags=2, cdisp=0,
            body="Erekem breaks all of his allies within $59463A1 yards out of snares, crowd-control and stun effects." },
          { id=7462, title="Erekem Guard", parent=0, child=7463, sib=7466, order=6, spell=0, icon=0, flags=0, cdisp=18628,
            body="Two Erekem Guards accompany Erekem." },
          { id=7463, title="Howling Screech", parent=7462, child=0, sib=7464, order=7, spell=0, icon="Interface\\icons\\spell_shadow_unsummonbuilding", flags=0, cdisp=0,
            body="Erekem Guards screech, reducing the movement speed and attack power of all players within $54462A1 yards for $54462d." },
          { id=7464, title="Gushing Wound", parent=7462, child=0, sib=7465, order=8, spell=0, icon="Interface\\icons\\ability_gouge", flags=0, cdisp=0,
            body="Erekem Guards wound a player, inflicting Physical damage every $39215t1 sec. for $39215d. This effect is removed by any healing effect." },
