            body="Erekem Guards strike a player, inflicting Physical damage." },
          { id=7466, title="Storm Unleashed", parent=0, child=7467, sib=0, order=10, spell=0, icon=0, flags=1, cdisp=0,
            body="If both of Erekem's Guards are killed, he becomes enraged and attacks players with new abilities" },
          { id=7467, title="Stormstrike", parent=7466, child=0, sib=7468, order=11, spell=0, icon="Interface\\icons\\ability_shaman_stormstrike", flags=0, cdisp=0,
