      { id=627, name="Moragg", order=2,
        uiMapID=168, x=0.679, y=0.5287, rootSection=7470,
        desc="Cyanigosa has enlisted Moragg to help her annihilate Dalaran's renegade magi. This nightmarish demon once served the Burning Legion, eviscerating Sargeras's enemies with the baleful gaze of his seven eyes. Now he will show Azeroth's heroes that one does not simply walk into the Violet Hold...",
        creatures = { {display=20590, file=607717, name="Moragg"} },
        loot = { {id=43408,pct=29.0,q=3,diff=6,name="Solitare of Reflecting Beams"}, {id=43382,pct=43.0,q=3,diff=6,name="Band of Eyes"}, {id=43409,pct=30.0,q=3,diff=6,name="Saliva Corroded Pike"}, {id=43410,pct=29.0,q=3,diff=6,name="Moragg's Chestguard"}, {id=43387,pct=43.0,q=3,diff=6,name="Shoulderplates of the Beholder"} },
        sections = {
