      { id=628, name="Ichoron", order=3,
        uiMapID=168, x=0.556, y=0.4037, rootSection=7475,
        desc="A foolish apprentice summoned this revenant from the Elemental Plane, only to discover that disgruntled soldiers of the Old Gods make poor pets. Ichoron slew her would-be master and has rotted in the Violet Hold ever since, eager to wreak vengeance on her jailors.",
