      { id=631, name="Zuramat the Obliterator", order=6,
        uiMapID=168, x=0.2719, y=0.3361, rootSection=7492,
        desc="It took one hundred of Dalaran's finest to subdue Zuramat; it took twice as many to clear the carnage from the killing field. The Obliterator's malevolence gives pause even to mad Malygos, who considers the void lord's appetite for magic distasteful. But genocide makes strange bedfellows.",
        creatures = { {display=27855, file=607825, name="Zuramat the Obliterator"} },
        loot = { {id=43403,pct=28.0,q=3,diff=6,name="Shroud of Darkness"}, {id=43358,pct=41.0,q=3,diff=6,name="Pendant of Shadow Beams"}, {id=43353,pct=44.0,q=3,diff=6,name="Void Sentry Legplates"}, {id=43404,pct=28.0,q=3,diff=6,name="Zuramat's Necklace"}, {id=43402,pct=28.0,q=3,diff=6,name="The Obliterator Greaves"} },
