  { id=284, name="Trial of the Champion", isRaid=false, minLevel=70,
    mapID=650, loreFDID=608263, bgFDID=608185, buttonFDID=608224,
    desc="Clouds blanket the skies of Icecrown and heroes gather beneath battle-worn banners in preparation for the coming storm. They say that even the darkest cloud has a silver lining. It is this hope that drives the men and women of the Argent Crusade: hope that the Light will see them through these trying times, hope that good will triumph over evil, hope that a hero blessed by the Light will come forth to put an end to the Lich King's dark reign.",
    encounters = {
      { id=634, name="Grand Champions", order=2,
        uiMapID=171, x=0.5123, y=0.5266, rootSection=7502,
        desc="The Lich King is relentless, his undead armies pouring forth to overwhelm his foes. To prepare would-be champions against him, Highlord Tirion Fordring presents a test of courage, endurance, and teamwork. His hardened veterans will weed out those who lack the stomach to face the ravening throngs of undead.",
        creatures = { {display=28587, file=607622, name="Mokra the Skullcrusher"}, {display=28637, file=0, name="Eressea Dawnsinger"}, {display=28597, file=0, name="Runok Wildmane"}, {display=28588, file=0, name="Zul'tore"}, {display=28589, file=0, name="Deathstalker Visceri"} },
        loot = { {id=47248,pct=0,q=4,diff=4,name="Treads of Dismal Fortune"}, {id=47249,pct=0,q=4,diff=4,name="Leggings of the Snowy Bramble"}, {id=47170,pct=0,q=4,diff=2,name="Belt of Fierce Competition"}, {id=47250,pct=0,q=4,diff=4,name="Pauldrons of the Deafening Gale"}, {id=47171,pct=0,q=4,diff=2,name="Legguards of Abandoned Fealty"}, {id=47172,pct=0,q=4,diff=2,name="Helm of the Bested Gallant"}, {id=47173,pct=0,q=4,diff=2,name="Bindings of the Wicked"}, {id=47493,pct=0,q=4,diff=4,name="Edge of Ruin"}, {id=47174,pct=0,q=4,diff=2,name="Binding of the Tranquil Glade"}, {id=47175,pct=0,q=4,diff=2,name="Scale Boots of the Outlander"}, {id=47243,pct=0,q=4,diff=4,name="Mark of the Relentless"}, {id=47244,pct=0,q=4,diff=4,name="Chestguard of the Ravenous Fiend"} },
        sections = {
