        desc="The Lich King is cunning and will use treachery to thwart his enemies. To that end, he has dispatched the Black Knight to eliminate promising candidates from Highlord Tirion Fordring's army. The undead's mere presence defiles the Crusaders' Coliseum, and those who prevail against him will prove their worthiness.",
        creatures = { {display=29837, file=607787, name="The Black Knight"} },
        loot = { {id=47564,pct=0,q=4,diff=6,name="Gaze of the Unknown"}, {id=47566,pct=0,q=4,diff=6,name="The Warlord's Depravity"}, {id=47215,pct=0,q=4,diff=6,name="Tears of the Vanquished"}, {id=47222,pct=0,q=4,diff=6,name="Uruka's Band of Zeal"}, {id=47216,pct=0,q=4,diff=6,name="The Black Heart"}, {id=47527,pct=0,q=4,diff=6,name="Embrace of Madness"}, {id=47231,pct=0,q=4,diff=6,name="Belt of Merciless Cruelty"}, {id=47232,pct=0,q=4,diff=6,name="Drape of the Undefeated"}, {id=47565,pct=0,q=4,diff=6,name="Vambraces of Unholy Command"}, {id=47568,pct=0,q=4,diff=6,name="True-aim Long Rifle"}, {id=47226,pct=0,q=4,diff=6,name="Mantle of Inconsolable Fear"}, {id=47230,pct=0,q=4,diff=6,name="Handwraps of Surrendered Hope"}, {id=47529,pct=0,q=4,diff=6,name="Mask of Distant Memory"}, {id=47227,pct=0,q=4,diff=6,name="Girdle of the Pallid Knight"}, {id=47567,pct=0,q=4,diff=6,name="Gauntlets of Revelation"}, {id=47569,pct=0,q=4,diff=6,name="Spectral Kris"}, {id=47229,pct=0,q=4,diff=6,name="Girdle of Arrogant Downfall"}, {id=47561,pct=0,q=4,diff=6,name="Gloves of the Dark Exile"}, {id=47563,pct=0,q=4,diff=6,name="Girdle of the Dauntless Conqueror"}, {id=47560,pct=0,q=4,diff=6,name="Boots of the Crackling Flame"}, {id=47562,pct=0,q=4,diff=6,name="Symbol of Redemption"}, {id=47221,pct=0,q=4,diff=6,name="Shoulderpads of the Infamous Knave"}, {id=49682,pct=0,q=4,diff=6,name="Black Knight's Rondel"}, {id=47220,pct=0,q=4,diff=6,name="Helm of the Violent Fray"}, {id=47228,pct=0,q=4,diff=6,name="Leggings of the Bloodless Knight"} },
