            body="The Risen Argent Herald leaps behind a random player, inflicting Physical damage." },
          { id=7592, title="Ghoul Explode", parent=7589, child=0, sib=0, order=12, spell=0, icon="Interface\\icons\\spell_deathknight_explode_ghoul", flags=0, cdisp=0,
            body="When the Risen Argent Herald reaches 30% health remaining or when The Black Knight is killed, he explodes, inflicting Shadow damage to all players within $67729A1 yards." },
          { id=7593, title="Phase 2: The Undead", parent=0, child=7596, sib=7594, order=13, spell=0, icon=0, flags=1, cdisp=0,
            body="When the Black Knight is killed, he is risen as a skeleton to continue his fight. He retains Plague Strike, Icy Touch and Obliterate from his living form and gains new abilities." },
          { id=7596, title="Desecration", parent=7593, child=0, sib=7597, order=14, spell=0, icon="Interface\\icons\\spell_shadow_shadowfiend", flags=0, cdisp=0,
            body="The Black Knight desecrates the ground at a player's location. The desecration inflicts Shadow damage and slows all players within it every second. The ground remains desecrated for $67779d." },
