  { id=285, name="Utgarde Keep", isRaid=false, minLevel=70,
    mapID=574, loreFDID=608265, bgFDID=608187, buttonFDID=608226,
    desc="Utgarde Keep was long thought to be abandoned, a relic of a lost civilization among the central cliffs of the Howling Fjord. Yet in recent days something has roused the fortress' slumbering residents, the vrykul.",
    encounters = {
      { id=638, name="Prince Keleseth", order=1,
        uiMapID=133, x=0.2896, y=0.627, rootSection=7601,
        desc="The Lich King deployed Keleseth to Utgarde Keep in hopes of harnessing the vrykul's potential for destruction. Upon arriving, the ambassador found a people who were more than eager to assist the Scourge. The keep has proved to be an excellent staging point for terrorizing the Howling Fjord, and Keleseth has no intention of losing it to insolent trespassers.",
        creatures = { {display=25338, file=607743, name="Prince Keleseth"} },
        loot = { {id=35572,pct=28.0,q=3,diff=6,name="Reinforced Velvet Helm"}, {id=37179,pct=21.0,q=3,diff=6,name="Infantry Assault Blade"}, {id=35571,pct=31.0,q=3,diff=6,name="Dragon Stabler's Gauntlets"}, {id=37180,pct=21.0,q=3,diff=6,name="Battlemap Hide Helm"}, {id=37177,pct=21.0,q=3,diff=6,name="Wand of the San'layn"}, {id=35570,pct=28.0,q=3,diff=6,name="Keleseth's Blade of Evocation"}, {id=37178,pct=22.0,q=3,diff=6,name="Strategist's Belt"} },
        sections = {
