            body="" },
          { id=7602, title="Frost Tomb", parent=0, child=0, sib=7603, order=2, spell=42672, icon="Interface\\icons\\spell_frost_frost", flags=0, cdisp=0,
            body="" },
          { id=7603, title="Vrykul Skeleton", parent=0, child=7604, sib=0, order=3, spell=0, icon=0, flags=1, cdisp=27651,
            body="Prince Keleseth calls for several Vrykul Skeletons to aid him in battle." },
          { id=7604, title="Decrepify", parent=7603, child=0, sib=7605, order=4, spell=59397, icon="Interface\\icons\\spell_shadow_raisedead", flags=0, cdisp=0,
            body="" },
          { id=7605, title="Unstoppable", parent=7603, child=0, sib=30234, order=5, spell=0, icon="Interface\\icons\\spell_deathknight_subversion", flags=0, cdisp=0,
            body="As long as Prince Keleseth lives, Vrykul Skeletons will return to life 20 seconds after being killed." },
