      { id=639, name="Skarvald & Dalronn", order=2,
        uiMapID=134, x=0.5874, y=0.6209, rootSection=7609,
        desc="It's a vrykul tradition to make unlikely partners work together. Some say it's to allow divergent abilities to complement each other; others say it's for the amusement of King Ymiron. Regardless, Skarvald and Dalronn are a perfect example of this custom. Between a vrykul's brawn and a human's necromantic arts, they will punish those who meddle with the Scourge.",
        creatures = { {display=24605, file=607774, name="Skarvald the Constructor"}, {display=26349, file=607575, name="Dalronn the Controller"} },
        loot = { {id=37183,pct=21.0,q=3,diff=6,name="Bindings of the Tunneler"}, {id=37182,pct=21.0,q=3,diff=6,name="Helmet of the Constructor"}, {id=35573,pct=30.0,q=3,diff=6,name="Arm Blade of Augelmir"}, {id=37184,pct=21.0,q=3,diff=6,name="Dalronn's Jerkin"}, {id=35575,pct=31.0,q=3,diff=6,name="Skarvald's Dragonskin Habergeon"}, {id=35574,pct=28.0,q=3,diff=6,name="Chestplate of the Northern Lights"}, {id=37181,pct=21.0,q=3,diff=6,name="Dagger of Betrayal"} },
