  { id=286, name="Utgarde Pinnacle", isRaid=false, minLevel=70,
    mapID=575, loreFDID=608266, bgFDID=608188, buttonFDID=608227,
    desc="Utgarde Keep was long thought to be abandoned, a relic of a lost civilization among the central cliffs of the Howling Fjord. Yet in recent days something has roused the fortress' slumbering residents, the vrykul.",
    encounters = {
      { id=641, name="Svala Sorrowgrave", order=1,
        uiMapID=136, x=0.3634, y=0.707, rootSection=7660,
        desc="Svala distinguished herself as Ingvar the Plunderer's lieutenant, leading perilous scouting missions in Horde and Alliance outposts. It was she who discovered the enemy's plans to invade Utgarde, giving the Lich King time to prepare. For her service, he has transformed her into a val'kyr, revered warrior maiden of the Scourge.",
        creatures = { {display=26096, file=607778, name="Svala Sorrowgrave"} },
        loot = { {id=37370,pct=21.0,q=3,diff=6,name="Cuffs of the Trussed Hall"}, {id=37037,pct=22.0,q=3,diff=6,name="Ritualistic Athame"}, {id=37369,pct=22.0,q=3,diff=6,name="Sorrowgrave's Breeches"}, {id=37040,pct=23.0,q=3,diff=6,name="Svala's Bloodied Shackles"}, {id=37038,pct=21.0,q=3,diff=6,name="Brazier Igniter"}, {id=37367,pct=22.0,q=3,diff=6,name="Echoing Stompers"}, {id=37368,pct=22.0,q=3,diff=6,name="Silent Spectator Shoulderpads"}, {id=37043,pct=24.0,q=3,diff=6,name="Tear-Linked Gauntlets"} },
        sections = {
          { id=7660, title="Sinister Strike", parent=0, child=0, sib=7661, order=1, spell=0, icon="Interface\\icons\\spell_shadow_ritualofsacrifice", flags=0, cdisp=0,
            body="Svala Sorrowgrave strikes a player, inflicting Physical damage." },
          { id=7661, title="Call Flames", parent=0, child=0, sib=7662, order=2, spell=0, icon="Interface\\icons\\spell_fire_lavaspawn", flags=0, cdisp=0,
            body="Svala Sorrowgrave summons flames from the nearby braziers that inflict Fire damage to a random player." },
          { id=7662, title="Ritual of the Sword", parent=0, child=7665, sib=0, order=3, spell=0, icon="Interface\\icons\\inv_sword_104", flags=0, cdisp=0,
            body="Svala Sorrowgrave summons a random player to her altar and begins to sacrifice them. While being sacrificed, three Ritual Channelers cast Paralyze on the player, stunning them until the channelers are killed." },
          { id=7665, title="Ritual Strike", parent=7662, child=0, sib=7666, order=4, spell=0, icon="Interface\\icons\\inv_sword_105", flags=1, cdisp=0,
            body="After 25 seconds, Svala's sword falls to the altar and inflits Shadow damage to all players within $48277A1 yards. In addition, any player hit by the sword becomes corrupted, causing Shadow damage every second for $48277d." },
          { id=7666, title="Ritual Channeler", parent=7662, child=7667, sib=0, order=5, spell=0, icon=0, flags=1, cdisp=10702,
            body="" },
          { id=7667, title="Paralyze", parent=7666, child=0, sib=7668, order=6, spell=0, icon="Interface\\icons\\spell_shadow_soulleech_3", flags=1, cdisp=0,
            body="Ritual Channelers focus on the player that Svala is sacrificing, stunning them for as long as the Ritual Channeler is alive." },
          { id=7668, title="Shadows in the Dark", parent=7666, child=0, sib=0, order=7, spell=0, icon="Interface\\icons\\spell_shadow_ragingscream", flags=3, cdisp=0,
            body="Ritual Channelers are surrounded with Shadows that have $59407h% chance of enveloping attackers, inflicting Shadow damage every $59408t1 sec for $59408d.  This effect stacks." },
        },
      },
      { id=642, name="Gortok Palehoof", order=2,
        uiMapID=137, x=0.6066, y=0.6885, rootSection=7669,
        desc="The vrykul keep many trophies at Utgarde Keep, and Gortok is among the most impressive. King Ymiron displays the frozen magnataur's cruel countenance as a reminder that even the most savage beasts are mere decorations for vrykul halls. This living statue will sow destruction if liberated, unleashing his wrath indiscriminately.",
        creatures = { {display=27419, file=607620, name="Gortok Palehoof"}, {display=26284, file=0, name="Ferocious Rhino"}, {display=26327, file=0, name="Frenzied Worgen"}, {display=24564, file=0, name="Massive Jormungar"}, {display=23999, file=0, name="Ravenous Furbolg"} },
        loot = { {id=37051,pct=21.0,q=3,diff=6,name="Seal of Valgarde"}, {id=37050,pct=24.0,q=3,diff=6,name="Trophy Gatherer"}, {id=37374,pct=22.0,q=3,diff=6,name="Ravenous Leggings of the Furbolg"}, {id=37048,pct=24.0,q=3,diff=6,name="Shroud of Resurrection"}, {id=37373,pct=21.0,q=3,diff=6,name="Massive Spaulders of the Jormungar"}, {id=37052,pct=21.0,q=3,diff=6,name="Reanimated Armor"}, {id=37371,pct=22.0,q=3,diff=6,name="Ring of the Frenzied Wolvar"}, {id=37376,pct=21.0,q=3,diff=6,name="Ferocious Pauldrons of the Rhino"} },
        sections = {
          { id=7669, title="Stasis Generator", parent=0, child=0, sib=7670, order=1, spell=0, icon=332402, flags=1, cdisp=0,
            body="Using the Stasis Generator causes two random hunting trophies to become active and attack players.\n\nOnce the hunting trophies are defeated, Gortok Palehoof becomes active.$[!2\n\nIn Heroic Difficulty, all four hunting trophies must be defeated before Gortok Plaehoof will activate.$]" },
          { id=7670, title="Stage 1: The Hunting Trophies", parent=0, child=7671, sib=7675, order=2, spell=0, icon=0, flags=1, cdisp=0,
            body="" },
          { id=7671, title="Ferocious Rhino", parent=7670, child=7676, sib=7672, order=3, spell=0, icon=0, flags=1, cdisp=26284,
            body="" },
          { id=7676, title="Grievous Wound", parent=7671, child=0, sib=7677, order=4, spell=0, icon="Interface\\icons\\ability_druid_primaltenacity", flags=0, cdisp=0,
            body="The Ferocious Rhino charges a random player, inflicting Physical damage and additional Physical damage every second. The Grievous Wound effect lasts for $48105d, or until the player is healed to full health." },
