      { id=643, name="Skadi the Ruthless", order=3,
        uiMapID=137, x=0.6844, y=0.3627, rootSection=7691,
        desc="The vrykul assign nicknames based on accomplishments. Cleansing a Drakkari bloodline or decapitating taunka might garner the appellation of \"dutiful,\" but it takes a true act of depravity to be called \"ruthless.\" Skadi earned his title long ago for relentlessly hunting down vrykul who sheltered the malformed infants, predecessors of humanity, condemned by Ymiron.",
        creatures = { {display=27418, file=607773, name="Skadi the Ruthless"} },
        loot = { {id=37384,pct=21.0,q=3,diff=6,name="Staff of Wayward Principles"}, {id=37055,pct=23.0,q=3,diff=6,name="Silken Amice of the Ymirjar"}, {id=37389,pct=21.0,q=3,diff=6,name="Crenelation Leggings"}, {id=37053,pct=20.0,q=3,diff=6,name="Amulet of Deflected Blows"}, {id=37377,pct=21.0,q=3,diff=6,name="Netherbreath Spellblade"}, {id=37056,pct=22.0,q=3,diff=6,name="Harpooner's Striders"}, {id=37057,pct=23.0,q=3,diff=6,name="Drake Rider's Tunic"}, {id=37379,pct=22.0,q=3,diff=6,name="Skadi's Iron Belt"}, {id=44151,pct=1.0,q=4,diff=4,name="Reins of the Blue Proto-Drake"} },
        sections = {
          { id=7691, title="Stage 1: Grauf", parent=0, child=7692, sib=7704, order=1, spell=0, icon=0, flags=1, cdisp=0,
            body="Skadi the Ruthless starts the fight by mounting his drake, Grauf. While mounted, Skadi will fly overhead and order Grauf to breathe freezing clouds onto players below.\n\nSkadi remains mounted until players fire three harpoons at Grauf by using the Harpoon Launcher." },
          { id=7692, title="Freezing Cloud", parent=7691, child=0, sib=7693, order=2, spell=0, icon="Interface\\icons\\spell_frost_arcticwinds", flags=0, cdisp=0,
            body="Grauf breathes a freezing cloud onto the ground, inflicting Frost damage to all players within it. The cloud persists on the ground for $47579d." },
          { id=7693, title="Harpoon Launcher", parent=7691, child=0, sib=7694, order=3, spell=0, icon=514302, flags=0, cdisp=0,
            body="Players who possess a harpoon can use the Harpoon Launchers found near Grauf to inflict Physical damage to him when he is within range of the launcher.\n\nHarpoons are obtained by killing Ymirjar Harpooners." },
          { id=7694, title="Ymirjar Harpooner", parent=7691, child=7695, sib=7698, order=4, spell=0, icon=0, flags=0, cdisp=25241,
            body="" },
          { id=7695, title="Throw", parent=7694, child=0, sib=7696, order=5, spell=0, icon="Interface\\icons\\ability_throw", flags=0, cdisp=0,
            body="Ymirjar Harpooners throw their weapon at a player, inflicting Physical damage." },
          { id=7696, title="Net", parent=7694, child=0, sib=7697, order=6, spell=0, icon="Interface\\icons\\ability_ensnare", flags=0, cdisp=0,
            body="Ymirjar Harpooners throw a net at a player, rooting them in place for $49092d." },
          { id=7697, title="Drop Harpoon", parent=7694, child=0, sib=0, order=7, spell=0, icon="Interface\\icons\\inv_spear_04", flags=0, cdisp=0,
            body="When Ymirjar Harpooners die, they drop a Harpoon on the ground that players can pick up and use with the Harpoon Launcher." },
          { id=7698, title="Ymirjar Warrior", parent=7691, child=7699, sib=7701, order=8, spell=0, icon=0, flags=0, cdisp=25240,
            body="" },
          { id=7699, title="Hamstring", parent=7698, child=0, sib=7700, order=9, spell=0, icon="Interface\\icons\\ability_shockwave", flags=0, cdisp=0,
            body="Ymirjar Warriors inflict Physical damage to a player, reducing their movement speed by $48639s2% for $48639d." },
          { id=7700, title="Strike", parent=7698, child=0, sib=0, order=10, spell=0, icon="Interface\\icons\\ability_rogue_ambush", flags=0, cdisp=0,
            body="Ymirjar Warriors strike a player, inflicting Physical damage." },
