            body="" },
          { id=7702, title="Shadow Bolt", parent=7701, child=0, sib=7703, order=12, spell=0, icon="Interface\\icons\\spell_shadow_shadowbolt", flags=0, cdisp=0,
            body="Ymirjar Witch Doctors hurl a bolt of dark magic at a player, inflicting Shadow damage." },
          { id=7703, title="Shrink", parent=7701, child=0, sib=0, order=13, spell=0, icon="Interface\\icons\\spell_shadow_antishadow", flags=0, cdisp=0,
            body="Ymirjar Witch Doctors shrink a player, reducing their strength and stamina by $49089s1 for $49089d." },
          { id=7704, title="Stage 2: Skadi the Ruthless", parent=0, child=7705, sib=0, order=14, spell=0, icon=0, flags=1, cdisp=0,
            body="" },
          { id=7705, title="Whirlwind", parent=7704, child=0, sib=7706, order=15, spell=0, icon="Interface\\icons\\ability_whirlwind", flags=0, cdisp=0,
            body="Skadi the Ruthless attacks all players within $50229A1 yards in a whirlwind of steel that lasts $50228d., inflicting Physical damage each time he spins. While whirlwinding, Skadi the Ruthless' movement speed is reduced by $50228s2%." },
          { id=7706, title="Crush", parent=7704, child=0, sib=7707, order=16, spell=0, icon="Interface\\icons\\inv_mace_52", flags=0, cdisp=0,
