      { id=644, name="King Ymiron", order=4,
        uiMapID=137, x=0.4153, y=0.5348, rootSection=7708,
        desc="Proud Ymiron ruled the northern wastes until the vrykul's long slumber relegated him to insignificance. He regained consciousness to find that his wife had been murdered, his lands besieged by enemies. He has cast off his mortality and demands vengeance, eager to show the terrible resolve of an awakened giant.",
        creatures = { {display=28019, file=607674, name="King Ymiron"} },
        loot = { {id=37390,pct=20.0,q=3,diff=6,name="Meteorite Whetstone"}, {id=37062,pct=21.0,q=3,diff=6,name="Crown of Forgotten Kings"}, {id=37064,pct=24.0,q=3,diff=6,name="Vestige of Haldor"}, {id=37409,pct=19.0,q=4,diff=6,name="Gilt-Edged Leather Gauntlets"}, {id=37067,pct=19.0,q=3,diff=6,name="Ceremonial Pyre Mantle"}, {id=37397,pct=20.0,q=3,diff=6,name="Gold Amulet of Kings"}, {id=37061,pct=23.0,q=3,diff=6,name="Tor's Crest"}, {id=37066,pct=23.0,q=3,diff=6,name="Ancient Royal Legguards"}, {id=37401,pct=18.0,q=4,diff=6,name="Red Sword of Courage"}, {id=37065,pct=20.0,q=3,diff=6,name="Ymiron's Blade"}, {id=37408,pct=19.0,q=4,diff=6,name="Girdle of Bane"}, {id=37398,pct=20.0,q=3,diff=6,name="Mantle of Discarded Ways"}, {id=37407,pct=20.0,q=4,diff=6,name="Sovereign's Belt"}, {id=37395,pct=20.0,q=3,diff=6,name="Ornamented Plate Regalia"}, {id=37058,pct=22.0,q=3,diff=6,name="Signet of Ranulf"}, {id=37060,pct=20.0,q=3,diff=6,name="Jeweled Coronation Sword"} },
        sections = {
          { id=7708, title="Gift of the Fallen Kings", parent=0, child=7711, sib=7709, order=1, spell=0, icon=0, flags=1, cdisp=0,
            body="When King Ymiron reaches 66% and 33% health remaining, he calls upon a fallen vrykul king to grant him a new ability. He retains this ability until he chooses a new fallen king.$[!2\n\nIn Heroic Difficulty, King Ymiron calls on a fallen king at 80%, 60%, 40% and 20% health remaining.$]" },
          { id=7711, title="Spirit Burst", parent=7708, child=0, sib=7713, order=2, spell=0, icon="Interface\\icons\\spell_shadow_haunting", flags=0, cdisp=0,
            body="Ranulf of the Screaming Abyss grants King Ymiron the ability to unleash a burst of spirit energy, inflicting Shadow damage to all players." },
          { id=7713, title="Summon Spirit Fount", parent=7708, child=0, sib=7715, order=3, spell=0, icon="Interface\\icons\\spell_shadow_teleport", flags=0, cdisp=0,
            body="Bjorn of the Black Storm grants King Ymiron the ability to summon a spirit fount that inflicts Shadow damage to a random player every second." },
          { id=7715, title="Spirit Strike", parent=7708, child=0, sib=7717, order=4, spell=0, icon="Interface\\icons\\spell_shadow_curseofachimonde", flags=0, cdisp=0,
            body="Haldor of the Rocky Cliffs grants King Ymiron the ability to strike a player, inflicting Physical damage and increasing their Physical damage taken for $48423d. This effect stacks up to $48423U times." },
          { id=7717, title="Summon Avenging Spirits", parent=7708, child=7721, sib=0, order=5, spell=0, icon="Interface\\icons\\spell_shadow_haunting", flags=0, cdisp=0,
            body="Tor of the Brutal Siege grants King Ymiron the ability to summon 4 Avenging Spirits to attack players." },
          { id=7721, title="Avenging Spirit", parent=7717, child=7722, sib=0, order=6, spell=0, icon=0, flags=1, cdisp=10771,
            body="" },
          { id=7722, title="Wither", parent=7721, child=0, sib=0, order=7, spell=0, icon="Interface\\icons\\spell_shadow_chilltouch", flags=1, cdisp=0,
            body="Avenging Spirit's melee attacks reduce all stats by $48585s1% for $48585d. This effect stacks up to $48585U times." },
          { id=7709, title="Screams of the Dead", parent=0, child=0, sib=7718, order=8, spell=0, icon="Interface\\icons\\spell_shadow_psychicscream", flags=0, cdisp=0,
            body="Whenever King Ymiron chooses a fallen king, he unleashes a bone chilling scream that stuns all players for $51750d." },
          { id=7718, title="Bane", parent=0, child=0, sib=7719, order=9, spell=0, icon="Interface\\icons\\spell_shadow_shadesofdarkness", flags=0, cdisp=0,
            body="King Ymiron is surrounded with an aura of Bane, which inflicts Shadow damage to all players within $48295A1 yards whenever he takes direct damage. This effect lasts for $48294d." },
          { id=7719, title="Dark Slash", parent=0, child=0, sib=7720, order=10, spell=0, icon="Interface\\icons\\spell_shadow_painspike", flags=0, cdisp=0,
            body="King Ymiron slashes a player, inflicting damage equal to half of their current health." },
          { id=7720, title="Fetid Rot", parent=0, child=0, sib=0, order=11, spell=0, icon="Interface\\icons\\ability_creature_disease_03", flags=0, cdisp=0,
            body="King Ymiron afflicts a player with Fetid Rot, inflicting Nature damage every $48291t1 sec. and decreasing healing received by $48291s2% for $48291d." },
        },
