}, {id=45087,pct=0,q=3,diff=0,name="Runed Orb"} },
        sections = {
          { id=17182, title="Overview", parent=0, child=17184, sib=17186, order=1, spell=0, icon=0, flags=0, cdisp=0,
            body="The Flame Leviathan will target and pursue after random Siege Vehicles and quickly destroy any vehicle that it catches! Use the Vehicles supplied by the Explorers' League to avoid and ensare the Flame Leviathan." },
          { id=17184, title="Siege Engine", parent=17182, child=0, sib=17183, order=2, spell=0, icon=0, flags=0, cdisp=0,
            body="$bullet;All Siege Vehicles should flee when Pursued by the Flame Leviathan.\n$bullet;Siege Engine Drivers should interrupt |cFF2959D3|Hspell:62396|h[Flame Vents]|h|r using |cFF2959D3|Hspell:62522|h[Electroshock]|h|r.\n$bullet;Siege Engine Passengers should shoot down Pyrite Ammo from overhead to resupply allies." },
          { id=17183, title="Demolisher", parent=17182, child=0, sib=17185, order=3, spell=0, icon=0, flags=0, cdisp=0,
            body="$bullet;All Siege Vehicles should flee when Pursued by the Flame Leviathan.\n$bullet;Demolisher Drivers can light allied |cFF2959D3|Hspell:62286|h[Tar]|h|r on fire.\n$bullet;Demolisher Passengers can also |cFF2959D3|Hspell:64414|h[Load Into Catapult]|h|r, allowing their driver to hurl them on top of the Flame Leviathan." },
          { id=17185, title="Chopper", parent=17182, child=0, sib=0, order=4, spell=0, icon=0, flags=0, cdisp=0,
            body="$bullet;All Siege Vehicles should flee when Pursued by the Flame Leviathan.\n$bullet;Use the Chopper to place |cFF2959D3|Hspell:62286|h[Tar]|h|r onto the battlefield." },
