      { id=1639, name="Razorscale", order=2,
        uiMapID=147, x=0.5458, y=0.2648, rootSection=17251,
        desc="Veranus, broodmother of the proto-drakes in the Storm Peaks, served the keeper Thorim until she was captured by Loken and twisted into a vicious weapon. Under his master's orders, Ignis the Furnace Master fused iron plates onto Razorscale's hide to enhance her deadly strikes.",
