        sections = {
          { id=17306, title="Overview", parent=0, child=17307, sib=17310, order=1, spell=0, icon=0, flags=0, cdisp=0,
            body="Defeating a member of the Assembly of Iron will heal the remaining two to full health and grant them |cFF2959D3|Hspell:61920|h[Supercharge]|h|r, which increases damage and grants access to additional abilities." },
