        sections = {
          { id=17330, title="Overview", parent=0, child=17331, sib=17338, order=1, spell=0, icon=0, flags=0, cdisp=0,
            body="Kologarn's arms can be destroyed, restricting his ability to use abilities. When Kologarn's Right or Left arm are destroyed Rubble will appear." },
          { id=17331, title="Damage Dealers", parent=17330, child=0, sib=17332, order=2, spell=0, icon=0, flags=0, cdisp=0,
            body="$bullet;Quickly attack the Right Arm when it casts |cFF2959D3|Hspell:64290|h[Stone Grip]|h|r to free your allies.\n$bullet;Flee when targeted with |cFF2959D3|Hspell:63346|h[Focused Eyebeam]|h|r to avoid heavy damage." },
          { id=17332, title="Healers", parent=17330, child=0, sib=17333, order=3, spell=0, icon=0, flags=0, cdisp=0,
            body="$bullet;Flee when targeted with |cFF2959D3|Hspell:63346|h[Focused Eyebeam]|h|r to avoid heavy damage.\n$bullet;Expect heavy damage on your allies afflicted with |cFF2959D3|Hspell:64290|h[Stone Grip]|h|r." },
          { id=17333, title="Tanks", parent=17330, child=0, sib=0, order=4, spell=0, icon=0, flags=0, cdisp=0,
            body="$bullet;Quickly gain the attention of the Rubble that spawn when an Arm of Kologarn is destroyed.\n$bullet;|cFF2959D3|Hspell:63356|h[Overhead Smash]|h|r inflicts heavy Physical damage and applies |cFF2959D3|Hspell:63355|h[Crunch Armor]|h|r." },
