      { id=1643, name="Auriaya", order=6,
        uiMapID=149, x=0.5126, y=0.5716, rootSection=17346,
        desc="Ulduar's archivist patrols the Observation Ring accompanied by ferocious cats. Years of solitude have weighed heavily on Auriaya, and the Old God's growing power seems to have destroyed the last shreds of her sanity.",
        creatures = { {display=28651, file=1385717, name="Auriaya"} },
        loot = { {id=45832,pct=19.0,q=4,diff=0,name="Mantle of the Preserver"}, {id=45440,pct=20.0,q=4,diff=0,name="Amice of the Stoic Watch"}, {id=45865,pct=20.0,q=4,diff=0,name="Raiments of the Corrupted"}, {id=45713,pct=21.0,q=4,diff=0,name="Nurturing Touch"}, {id=45437,pct=20.0,q=4,diff=0,name="Runescribed Blade"}, {id=45709,pct=19.0,q=4,diff=0,name="Nimble Climber's Belt"}, {id=45315,pct=19.0,q=4,diff=0,name="Stonerender"}, {id=45708,pct=20.0,q=4,diff=0,name="Archaedas' Lost Legplates"}, {id=45326,pct=19.0,q=4,diff=0,name="Platinum Band of the Aesir"}, {id=45320,pct=20.0,q=4,diff=0,name="Shoulderplates of the Eternal"}, {id=45864,pct=20.0,q=4,diff=0,name="Cover of the Keepers"}, {id=45866,pct=19.0,q=4,diff=0,name="Elemental Focus Stone"}, {id=45438,pct=19.0,q=4,diff=0,name="Ring of the Faithful Servant"}, {id=45435,pct=19.0,q=4,diff=0,name="Cowl of the Absolute"}, {id=45334,pct=18.0,q=4,diff=0,name="Unbreakable Chestguard"}, {id=45707,pct=19.0,q=4,diff=0,name="Shieldwall of the Breaker"}, {id=45327,pct=20.0,q=4,diff=0,name="Siren's Cry"}, {id=45441,pct=20.0,q=4,diff=0,name="Sandals of the Ancient Keeper"}, {id=45439,pct=20.0,q=4,diff=0,name="Unwavering Stare"}, {id=45711,pct=19.0,q=4,diff=0,name="Ironaya's Discarded Mantle"}, {id=45319,pct=19.0,q=4,diff=0,name="Cloak of the Makers"}, {id=45434,pct=20.0,q=4,diff=0,name="Greaves of the Rockmender"}, {id=45712,pct=20.0,q=4,diff=0,name="Chestplate of Titanic Fury"}, {id=45325,pct=20.0,q=4,diff=0,name="Gloves of the Stonereaper"}, {id=45038,pct=40.0,q=5,diff=0,name="Fragment of Val'anyr"}, {id=45087,pct=0,q=3,diff=0,name="Runed Orb"} },
        sections = {
          { id=17346, title="Overview", parent=0, child=17347, sib=17350, order=1, spell=0, icon=0, flags=0, cdisp=0,
            body="Auriaya patrols the Observation Ring with her four Sanctum Sentries which will ravage their target with a |cFF2959D3|Hspell:64666|h[Savage Pounce]|h|r when engaged. She summons other guardians during the encounter which she commands to disrupt her enemies." },
          { id=17347, title="Damage Dealers", parent=17346, child=0, sib=17348, order=2, spell=0, icon=0, flags=0, cdisp=0,
            body="$bullet;Stop casting spells to avoid being interrupted while the Feral Defender is casting |cFF2959D3|Hspell:64496|h[Feral Rush]|h|r.\n$bullet;Interrupt Auriaya's casts of |cFF2959D3|Hspell:64389|h[Sentinel Blast]|h|r.\n$bullet;Assist in splitting the damage of |cFF2959D3|Hspell:64422|h[Sonic Screech]|h|r." },
          { id=17348, title="Healers", parent=17346, child=0, sib=17349, order=3, spell=0, icon=0, flags=0, cdisp=0,
            body="$bullet;Be prepared for heavy damage when Auriaya is engaged from her Sanctum Sentry's |cFF2959D3|Hspell:64666|h[Savage Pounce]|h|r.\n$bullet;Assist in splitting the damage of |cFF2959D3|Hspell:64422|h[Sonic Screech]|h|r.\n$bullet;Stop casting spells to avoid being interrupted while the Feral Defender is casting |cFF2959D3|Hspell:64496|h[Feral Rush]|h|r." },
          { id=17349, title="Tanks", parent=17346, child=0, sib=0, order=4, spell=0, icon=0, flags=0, cdisp=0,
            body="$bullet;Be prepared for heavy damage when Auriaya is engaged from her Sanctum Sentry's |cFF2959D3|Hspell:64666|h[Savage Pounce]|h|r.\n$bullet;Be quick to grab the attention of the Feral Defender." },
