        sections = {
          { id=17441, title="Overview", parent=0, child=17442, sib=17445, order=1, spell=0, icon=0, flags=0, cdisp=0,
            body="Break out allies trapped in |cFF2959D3|Hspell:61990|h[Flash Freeze]|h|r. Once freed they will provide assistance in various ways." },
