      { id=1645, name="Thorim", order=8,
        uiMapID=149, x=0.722, y=0.4855, rootSection=17520,
        desc="For years, Thorim believed that ice giants had murdered his beloved wife Sif. Thorim turned his wrath upon his allies and fell into despair. When he learned that his brother Loken was responsible for the crime, Loken captured Thorim and brought him to Ulduar, where the Old God clouded the keeper's mind.",
        creatures = { {display=28977, file=1385770, name="Thorim"}, {display=28488, file=0, name="Sif"} },
        loot = { {id=45474,pct=2.0,q=4,diff=0,name="Pauldrons of the Combatant"}, {id=45469,pct=14.0,q=4,diff=0,name="Sif's Promise"}, {id=45659,pct=25.0,q=4,diff=0,name="Spaulders of the Wayward Conqueror"}, {id=45927,pct=17.0,q=4,diff=0,name="Handwraps of Resonance"}, {id=45638,pct=50.0,q=4,diff=0,name="Crown of the Wayward Conqueror"}, {id=45468,pct=17.0,q=4,diff=0,name="Leggings of Lost Love"}, {id=45893,pct=19.0,q=4,diff=0,name="Guise of the Midgard Serpent"}, {id=45931,pct=5.0,q=4,diff=0,name="Mjolnir Runestone"}, {id=45473,pct=2.0,q=4,diff=0,name="Embrace of the Gladiator"}, {id=45472,pct=1.0,q=4,diff=0,name="Warhelm of the Champion"}, {id=45470,pct=2.0,q=4,diff=0,name="Wisdom's Hold"}, {id=45933,pct=4.0,q=4,diff=0,name="Pendant of the Shallow Grave"}, {id=45471,pct=1.0,q=4,diff=0,name="Fate's Clutch"}, {id=45463,pct=18.0,q=4,diff=0,name="Vulmir, the Northern Tempest"}, {id=45640,pct=71.0,q=4,diff=0,name="Crown of the Wayward Vanquisher"}, {id=45639,pct=57.0,q=4,diff=0,name="Crown of the Wayward Protector"}, {id=45660,pct=28.0,q=4,diff=0,name="Spaulders of the Wayward Protector"}, {id=45661,pct=34.0,q=4,diff=0,name="Spaulders of the Wayward Vanquisher"}, {id=45930,pct=5.0,q=4,diff=0,name="Combatant's Bootblade"}, {id=45928,pct=5.0,q=4,diff=0,name="Gauntlets of the Thunder God"}, {id=45467,pct=17.0,q=4,diff=0,name="Belt of the Betrayed"}, {id=45895,pct=18.0,q=4,diff=0,name="Belt of the Blood Pit"}, {id=45894,pct=17.0,q=4,diff=0,name="Leggings of Unstable Discharge"}, {id=45466,pct=17.0,q=4,diff=0,name="Scale of Fates"}, {id=45929,pct=4.0,q=4,diff=0,name="Sif's Remembrance"}, {id=45570,pct=1.0,q=4,diff=0,name="Skyforge Crossbow"}, {id=45892,pct=18.0,q=4,diff=0,name="Legacy of Thunder"}, {id=45038,pct=40.0,q=5,diff=0,name="Fragment of Val'anyr"}, {id=45087,pct=0,q=3,diff=0,name="Runed Orb"} },
        sections = {
          { id=17520, title="Overview", parent=0, child=17521, sib=17524, order=1, spell=0, icon=0, flags=0, cdisp=0,
            body="Thorim calls in Dark Rune forces to engage players that are in the Arena until allies are able to reach Thorim by traveling through the Hallway. Once players reach Thorim he will leap into the arena and use powerful Lightning attacks to defeat his foes." },
          { id=17521, title="Damage Dealers", parent=17520, child=0, sib=17522, order=2, spell=0, icon=0, flags=0, cdisp=0,
            body="$bullet;While in the Arena interrupt the Dark Rune Acolyte's |cFF2959D3|Hspell:62334|h[Greater Heal]|h|r and the |cFF2959D3|Hspell:62446|h[Runic Mending]|h|r cast by Dark Rune Evokers.\n$bullet;Avoid Thorim's |cFF2959D3|Hspell:62279|h[Lightning Charge]|h|r once Stage Two begins.\n$bullet;While in the Hallway avoid|cFF2959D3|Hspell:62465|h[Runic Smash]|h|r cast by the Runic Colossus." },
          { id=17522, title="Healers", parent=17520, child=0, sib=17523, order=3, spell=0, icon=0, flags=0, cdisp=0,
            body="$bullet;Avoid Thorim's |cFF2959D3|Hspell:62279|h[Lightning Charge]|h|r once Stage Two begins." },
          { id=17523, title="Tanks", parent=17520, child=0, sib=0, order=4, spell=0, icon=0, flags=0, cdisp=0,
            body="$bullet;Avoid Thorim's |cFF2959D3|Hspell:62279|h[Lightning Charge]|h|r once Stage Two begins.\n$bullet;While in the Hallway avoid|cFF2959D3|Hspell:62465|h[Runic Smash]|h|r cast by the Runic Colossus.\n$bullet;While in the Hallway avoid|cFF2959D3|Hspell:62339|h[Smash]|h|r cast by the Runic Colossus once it is engaged.\n$bullet;Take turns tanking Thorim to manage |cFF2959D3|Hspell:62130|h[Unbalancing Strike]|h|r." },
