        sections = {
          { id=17375, title="Overview", parent=0, child=17376, sib=17413, order=1, spell=0, icon=0, flags=0, cdisp=0,
            body="During Stage One stacks of |cFF2959D3|Hspell:62519|h[Attuned to Nature]|h|r must be removed by defeating the Allies of Nature. Once the Allies of Nature are defeated Stage Two will begin." },
          { id=17376, title="Damage Dealers", parent=17375, child=0, sib=17377, order=2, spell=0, icon=0, flags=0, cdisp=0,
            body="$bullet;Spread out to avoid damage from |cFF2959D3|Hspell:62598|h[Detonate]|h|r while the Detonating Lashers are present.\n$bullet;Interrupt |cFF2959D3|Hspell:62648|h[Lightning Lash]|h|r cast by the Storm Lasher.\n$bullet;Be near a Healthy Spore to prevent being Silenced or Pacified by the Ancient Conservator's |cFF2959D3|Hspell:62532|h[Conservator's Grip]|h|r.\n$bullet;Destroy the Lifebinder's Gift before Freya is able to cast |cFF2959D3|Hspell:62584|h[Lifebinding Heal]|h|r." },
          { id=17377, title="Healers", parent=17375, child=0, sib=17378, order=3, spell=0, icon=0, flags=0, cdisp=0,
            body="$bullet;Spread out to avoid damage from |cFF2959D3|Hspell:62598|h[Detonate]|h|r while the Detonating Lashers are present.\n$bullet;Be near a Healthy Spore to prevent being Silenced or Pacified by the Ancient Conservator's |cFF2959D3|Hspell:62532|h[Conservator's Grip]|h|r." },
          { id=17378, title="Tanks", parent=17375, child=0, sib=0, order=4, spell=0, icon=0, flags=0, cdisp=0,
            body="$bullet;Be near a Healthy Spore to prevent being Silenced or Pacified by the Ancient Conservator's |cFF2959D3|Hspell:62532|h[Conservator's Grip]|h|r.\n$bullet;Be quick to gain the attention of enemies summoned by Freya's |cFF2959D3|Hspell:62678|h[Summon Allies of Nature]|h|r." },
