      { id=1647, name="Mimiron", order=10,
        uiMapID=151, x=0.4362, y=0.4124, rootSection=17579,
        desc="A brilliant innovator, Mimiron has crafted countless mechanisms throughout the history of Azeroth that have inspired awe and wonder. But since falling under Loken's disturbed influence, this watcher of Ulduar has only constructed machines of war and destruction.",
        creatures = { {display=28578, file=1385754, name="Mimiron"} },
        loot = { {id=45993,pct=1.0,q=4,diff=0,name="Mimiron's Flight Goggles"}, {id=45495,pct=0,q=4,diff=0,name="Conductive Seal"}, {id=45989,pct=0.3,q=4,diff=0,name="Tempered Mercury Greaves"}, {id=45649,pct=37.0,q=4,diff=0,name="Helm of the Wayward Vanquisher"}, {id=45976,pct=20.0,q=4,diff=0,name="Static Charge Handwraps"}, {id=45641,pct=45.0,q=4,diff=0,name="Gauntlets of the Wayward Conqueror"}, {id=45643,pct=68.0,q=4,diff=0,name="Gauntlets of the Wayward Vanquisher"}, {id=45492,pct=25.0,q=4,diff=0,name="Malleable Steelweave Mantle"}, {id=45972,pct=0.1,q=4,diff=0,name="Pulse Baton"}, {id=45648,pct=75.0,q=4,diff=0,name="Helm of the Wayward Protector"}, {id=45497,pct=0,q=4,diff=0,name="Crown of Luminescence"}, {id=45489,pct=15.0,q=4,diff=0,name="Insanity's Grip"}, {id=45494,pct=0,q=4,diff=0,name="Delirium's Touch"}, {id=45975,pct=11.0,q=4,diff=0,name="Cable of the Metrognome"}, {id=45496,pct=0.3,q=4,diff=0,name="Titanskin Cloak"}, {id=45491,pct=17.0,q=4,diff=0,name="Waistguard of the Creator"}, {id=45620,pct=0,q=4,diff=0,name="Starshard Edge"}, {id=45974,pct=75.0,q=4,diff=0,name="Shoulderguards of Assimilation"}, {id=45988,pct=0,q=4,diff=0,name="Greaves of the Iron Army"}, {id=45493,pct=11.0,q=4,diff=0,name="Asimov's Drape"}, {id=45642,pct=50.0,q=4,diff=0,name="Gauntlets of the Wayward Protector"}, {id=45490,pct=17.0,q=4,diff=0,name="Pandora's Plea"}, {id=45973,pct=19.0,q=4,diff=0,name="Stylish Power Cape"}, {id=45982,pct=0.3,q=4,diff=0,name="Fused Alloy Legplates"}, {id=45647,pct=28.0,q=4,diff=0,name="Helm of the Wayward Conqueror"}, {id=45663,pct=0,q=4,diff=0,name="Armbands of Bedlam"}, {id=45990,pct=0.1,q=4,diff=0,name="Fusion Blade"}, {id=45038,pct=40.0,q=5,diff=0,name="Fragment of Val'anyr"}, {id=45087,pct=0,q=3,diff=0,name="Runed Orb"} },
        sections = {
          { id=17579, title="Overview", parent=0, child=17580, sib=17583, order=1, spell=0, icon=0, flags=0, cdisp=0,
            body="Mimiron engages his enemies with inventions rather than directly in combat. The Leviathan MK II is a deadly vehicle that assaults the Tank with powerful attacks, the VX-001 which strikes enemies with rocket blasts and laser barrages, the Aerial Command Unit which engages enemies from the skies, and finally the V0-L7R-0N unit, which combines the might of all of his inventions." },
          { id=17580, title="Damage Dealers", parent=17579, child=0, sib=17581, order=2, spell=0, icon=0, flags=0, cdisp=0,
            body="$bullet;Avoid the Leviathan Mk II's |cFF2959D3|Hspell:63016|h[Proximity Mines]|h|r when fleeing from |cFF2959D3|Hspell:63631|h[Shock Blast]|h|r.\n$bullet;Be spread apart to avoid the Leviathan Mk II's |cFF2959D3|Hspell:63666|h[Napalm Shell]|h|r.\n$bullet;Rotate away from VX-001's |cFF2959D3|Hspell:63293|h[P3Wx2 Laser Barrage]|h|r ability.\n$bullet;Use the Magnetic Core dropped by the Assault Bot to ground the Aerial Command Unit." },
          { id=17581, title="Healers", parent=17579, child=0, sib=17582, order=3, spell=0, icon=0, flags=0, cdisp=0,
            body="$bullet;Be spread apart to avoid the Leviathan Mk II's |cFF2959D3|Hspell:63666|h[Napalm Shell]|h|r.\n$bullet;Prepare for heavy damage on the Tank when the Leviathan Mk II casts |cFF2959D3|Hspell:62997|h[Plasma Blast]|h|r.\n$bullet;Rotate away from VX-001's |cFF2959D3|Hspell:63293|h[P3Wx2 Laser Barrage]|h|r ability." },
          { id=17582, title="Tanks", parent=17579, child=0, sib=0, order=4, spell=0, icon=0, flags=0, cdisp=0,
            body="$bullet;Prepare for heavy damage when the Leviathan Mk II casts |cFF2959D3|Hspell:62997|h[Plasma Blast]|h|r.\n$bullet;Rotate away from VX-001's |cFF2959D3|Hspell:63293|h[P3Wx2 Laser Barrage]|h|r ability.\n$bullet;Use the Magnetic Core dropped by the Assault Bot to ground the Aerial Command Unit." },
