      { id=1649, name="Yogg-Saron", order=12,
        uiMapID=150, x=0.6838, y=0.3994, rootSection=17653,
        desc="The lucid dream. The monster in your nightmares. The fiend of a thousand faces.\n\nAll must bend to the master's will. Your petty quarrels only make him stronger.",
