        loot = { {id=45532,pct=17.0,q=4,diff=0,name="Cowl of Dark Whispers"}, {id=46022,pct=8.0,q=4,diff=0,name="Pendant of a Thousand Maws"}, {id=45524,pct=13.0,q=4,diff=0,name="Chestguard of Insidious Intent"}, {id=46031,pct=25.0,q=4,diff=0,name="Touch of Madness"}, {id=46024,pct=10.0,q=4,diff=0,name="Kingsbane"}, {id=45530,pct=18.0,q=4,diff=0,name="Sanity's Bond"}, {id=46028,pct=17.0,q=4,diff=0,name="Faceguard of the Eyeless Horror"}, {id=46068,pct=0,q=4,diff=0,name="Amice of Inconceivable Horror"}, {id=46016,pct=17.0,q=4,diff=0,name="Abaddon"}, {id=46019,pct=12.0,q=4,diff=0,name="Leggings of the Insatiable"}, {id=46095,pct=0,q=4,diff=0,name="Soul-Devouring Cinch"}, {id=45525,pct=11.0,q=4,diff=0,name="Godbane Signet"}, {id=45533,pct=1.0,q=4,diff=0,name="Dark Edge of Depravity"}, {id=45529,pct=25.0,q=4,diff=0,name="Shawl of Haunted Memories"}, {id=45537,pct=1.0,q=4,diff=0,name="Treads of the False Oracle"}, {id=45636,pct=50.0,q=4,diff=0,name="Chestguard of the Wayward Protector"}, {id=45527,pct=9.0,q=4,diff=0,name="Soulscribe"}, {id=45656,pct=59.0,q=4,diff=0,name="Mantle of the Wayward Conqueror"}, {id=46018,pct=35.0,q=4,diff=0,name="Deliverance"}, {id=46030,pct=17.0,q=4,diff=0,name="Treads of the Dragon Council"}, {id=45635,pct=52.0,q=4,diff=0,name="Chestguard of the Wayward Conqueror"}, {id=46067,pct=0,q=4,diff=0,name="Hammer of Crushing Whispers"}, {id=46025,pct=23.0,q=4,diff=0,name="Devotion"}, {id=45536,pct=1.0,q=4,diff=0,name="Legguards of Cunning Deception"}, {id=46097,pct=0,q=4,diff=0,name="Caress of Insanity"}, {id=45531,pct=16.0,q=4,diff=0,name="Chestguard of the Fallen God"}, {id=45521,pct=15.0,q=4,diff=0,name="Earthshaper"}, {id=45637,pct=27.0,q=4,diff=0,name="Chestguard of the Wayward Vanquisher"}, {id=45535,pct=0,q=4,diff=0,name="Show of Faith"}, {id=46021,pct=12.0,q=4,diff=0,name="Royal Seal of King Llane"}, {id=45534,pct=0,q=4,diff=0,name="Seal of the Betrayed King"}, {id=45657,pct=54.0,q=4,diff=0,name="Mantle of the Wayward Protector"}, {id=45658,pct=66.0,q=4,diff=0,name="Mantle of the Wayward Vanquisher"}, {id=45522,pct=20.0,q=4,diff=0,name="Blood of the Old God"}, {id=46096,pct=0,q=4,diff=0,name="Signet of Soft Lament"}, {id=45523,pct=18.0,q=4,diff=0,name="Garona's Guise"}, {id=45038,pct=40.0,q=5,diff=0,name="Fragment of Val'anyr"}, {id=46312,pct=100.0,q=4,diff=0,name="Vanquished Clutches of Yogg-Saron"}, {id=45693,pct=100.0,q=4,diff=0,name="Mimiron's Head"}, {id=45087,pct=0,q=3,diff=0,name="Runed Orb"} },
        sections = {
          { id=17653, title="Overview", parent=0, child=17654, sib=17670, order=1, spell=0, icon=0, flags=0, cdisp=0,
            body="Sara must be damaged by Guardians of Yogg-Saron's |cFF2959D3|Hspell:62714|h[Shadow Nova]|h|r, once damaged significantly, Yogg Saron will reveal himself and begin to attack the sanity of his enemies, which is depleted will turn his enemies against one another. \n\nPeriodically portals will appear which grant players access to the Brain of Yogg-Saron, while inside they must dispel illusions in order to escape, before they are afflicted with |cFF2959D3|Hspell:64059|h[Induce Madness]|h|r. \n\nWhen the Brain of Yogg-Saron reaches 30% health remaining, Yogg Saron's |cFF2959D3|Hspell:63894|h[Shadowy Barrier]|h|r will fall and he can be assaulted directly." },
          { id=17654, title="Damage Dealers", parent=17653, child=0, sib=17655, order=2, spell=0, icon=0, flags=0, cdisp=0,
            body="$bullet;During Stage One defeat the Guardians of Yogg-Saron nearby Sara in order to damage her.\n$bullet;Enter the Descent into Madness and defeat the illusions to gain access to the Brain of Yogg-Saron.\n$bullet;Avoid losing all of your |cFF2959D3|Hspell:63050|h[Sanity]|h|r.\n$bullet;Stand close to your allies when connected by |cFF2959D3|Hspell:63802|h[Brain Link]|h|r." },
          { id=17655, title="Healers", parent=17653, child=0, sib=17656, order=3, spell=0, icon=0, flags=0, cdisp=0,
            body="$bullet;Avoid losing all of your |cFF2959D3|Hspell:63050|h[Sanity]|h|r.\n$bullet;Enter the Descent into Madness and defeat the illusions to gain access to the Brain of Yogg-Saron.\n$bullet;Stand close to your allies when connected by |cFF2959D3|Hspell:63802|h[Brain Link]|h|r." },
          { id=17656, title="Tank", parent=17653, child=0, sib=0, order=4, spell=0, icon=0, flags=0, cdisp=0,
            body="$bullet;Position Guardians of Yogg-Saron near Sara to damage her with |cFF2959D3|Hspell:62714|h[Shadow Nova]|h|r.\n$bullet;Avoid losing all of your |cFF2959D3|Hspell:63050|h[Sanity]|h|r.\n$bullet;Be quick to grab the attention of Crusher Tentacles and Immortal Guardians as they spawn.\n$bullet;Prevent Immortal Guardians from healing by moving ones with |cFF2959D3|Hspell:64468|h[ Empowering Shadows]|h|r away." },
          { id=17670, title="The Keepers of Ulduar", parent=0, child=17671, sib=17658, order=5, spell=0, icon=0, flags=0, cdisp=0,
            body="Speak to the Keepers of Ulduar and they will join the battle and provide additional buffs and benefits while engaged with Yogg-Saron." },
