for _, inst in ipairs(NEW) do
  inst["_wotlk"] = true
  -- supersede any earlier-loaded instance sharing this JournalInstanceID
  -- (Blizzard reuses IDs across expansions, e.g. Naxxramas 754).
  for i = #INST, 1, -1 do if INST[i].id == inst.id then table.remove(INST, i) end end
  INST[#INST+1] = inst
end

